export type RequestStatus = "backlog" | "in_progress" | "review" | "delivered";
export type Priority = "low" | "normal" | "high" | "urgent";
export type Plan = "free" | "starter" | "growth" | "scale";
export type ActivityType =
  | "request_created"
  | "request_delivered"
  | "client_added"
  | "request_assigned"
  | "comment_added"
  | "brief_generated";
export type TrendDirection = "up" | "down" | "flat";
export type ServiceCategory =
  | "design"
  | "development"
  | "seo"
  | "content"
  | "video"
  | "ads";
export type AssigneeRole = "owner" | "designer" | "developer" | "pm";
export type IconName =
  | "users"
  | "inbox"
  | "activity"
  | "dollar-sign"
  | "clock";

export interface Client {
  id: string;
  name: string;
  email: string;
  avatarUrl: string;
  company: string;
  plan: Plan;
  activeRequests: number;
  mrr: number;
  joinedAt: string;
}

export interface Service {
  id: string;
  name: string;
  description: string;
  flatPrice: number;
  turnaroundDays: number;
  category: ServiceCategory;
  activeClients: number;
}

export interface Assignee {
  id: string;
  name: string;
  avatarUrl: string;
  role: AssigneeRole;
}

export interface Request {
  id: string;
  clientId: string;
  title: string;
  rawMessage: string;
  status: RequestStatus;
  priority: Priority;
  assigneeId: string;
  createdAt: string;
  slaDueAt: string;
  tags: readonly string[];
}

export interface KpiMetric {
  id: string;
  label: string;
  value: string;
  rawValue: number;
  delta: number;
  trend: TrendDirection;
  iconName: IconName;
}

export interface ActivityEvent {
  id: string;
  actorId: string;
  actorName: string;
  action: string;
  target: string;
  timestamp: string;
  type: ActivityType;
}

export type SlaStatus = "ok" | "warning" | "breached";

export function getSlaStatus(slaDueAt: string, now = "2026-04-10T12:00:00Z"): SlaStatus {
  const dueMs = new Date(slaDueAt).getTime();
  const nowMs = new Date(now).getTime();
  const diffHours = (dueMs - nowMs) / (1000 * 60 * 60);
  if (diffHours < 0) return "breached";
  if (diffHours < 24) return "warning";
  return "ok";
}

