import { formatSlaChip } from "@/lib/utils/time";
import { cn } from "@/lib/utils";

const toneClasses = {
  ok: "bg-muted text-muted-foreground",
  warning: "bg-amber-50 text-amber-700 ring-1 ring-amber-200",
  breached: "bg-rose-50 text-rose-700 ring-1 ring-rose-200",
} as const;

export function SlaChip({ slaDueAt }: { slaDueAt: string }) {
  const { label, tone } = formatSlaChip(slaDueAt);
  return (
    <span
      className={cn(
        "inline-flex items-center rounded-full px-2 py-0.5 text-[10px] font-medium whitespace-nowrap",
        toneClasses[tone]
      )}
    >
      {label}
    </span>
  );
}
import type { RequestStatus } from "@/lib/types";

interface StatusBadgeProps {
  status: RequestStatus;
}

const STATUS_MAP: Record<
  RequestStatus,
  { label: string; className: string }
> = {
  backlog: {
    label: "Backlog",
    className: "bg-sky-100 text-sky-700 ring-1 ring-sky-200",
  },
  in_progress: {
    label: "In Progress",
    className: "bg-slate-100 text-slate-700 ring-1 ring-slate-200",
  },
  review: {
    label: "Review",
    className: "bg-amber-100 text-amber-800 ring-1 ring-amber-200",
  },
  delivered: {
    label: "Delivered",
    className: "bg-emerald-100 text-emerald-700 ring-1 ring-emerald-200",
  },
};

export function StatusBadge({ status }: StatusBadgeProps) {
  const config = STATUS_MAP[status];
  return (
    <span
      className={`inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium whitespace-nowrap ${config.className}`}
    >
      {config.label}
    </span>
  );
}
import { Flame } from "lucide-react";
import type { Priority } from "@/lib/types";

interface PriorityBadgeProps {
  priority: Priority;
}

export function PriorityBadge({ priority }: PriorityBadgeProps) {
  if (priority === "normal") {
    return (
      <span className="text-xs text-muted-foreground">Normal</span>
    );
  }

  if (priority === "low") {
    return (
      <span className="inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium whitespace-nowrap bg-slate-100 text-slate-500 ring-1 ring-slate-200">
        Low
      </span>
    );
  }

  if (priority === "high") {
    return (
      <span className="inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium whitespace-nowrap bg-amber-100 text-amber-700 ring-1 ring-amber-200">
        High
      </span>
    );
  }

  // urgent
  return (
    <span className="inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-xs font-medium whitespace-nowrap bg-red-100 text-red-700 ring-1 ring-red-200">
      <Flame className="size-3" />
      Urgent
    </span>
  );
}

