import type { Metadata } from "next";
import { Inter } from "next/font/google";
import { cn } from "@/lib/utils";
import "./globals.css";

const inter = Inter({
  subsets: ["latin"],
  variable: "--font-sans",
});

export const metadata: Metadata = {
  title: "Clientloop — AI-native client HQ for productized agencies",
  description:
    "Turn messy client requests into structured briefs with AI. Flat pricing, Stripe + Razorpay, mobile-first. Built for modern productized agencies.",
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html
      lang="en"
      suppressHydrationWarning
      className={`${inter.variable} h-full antialiased`}
    >
      <body className={cn(inter.variable, "font-sans min-h-full flex flex-col bg-background text-foreground")}>{children}</body>
    </html>
  );
}

