import type { SnoozePresetId } from "@/lib/types";
import { getAnchoredNow } from "@/lib/utils/time";

export interface SnoozePreset {
  id: SnoozePresetId;
  label: string;
  hint: string;
}

export const SNOOZE_PRESETS: readonly SnoozePreset[] = [
  { id: "1h", label: "In 1 hour", hint: "Quick pause" },
  { id: "tomorrow", label: "Tomorrow", hint: "9:00 am" },
  { id: "next_week", label: "Next week", hint: "Monday 9:00 am" },
];

export function resolveSnoozeTime(preset: SnoozePresetId, now: Date = getAnchoredNow()): string {
  const next = new Date(now);
  switch (preset) {
    case "1h":
      next.setUTCHours(next.getUTCHours() + 1);
      return next.toISOString();
    case "tomorrow": {
      next.setUTCDate(next.getUTCDate() + 1);
      next.setUTCHours(9, 0, 0, 0);
      return next.toISOString();
    }
    case "next_week": {
      const day = next.getUTCDay();
      // 1 = Monday. Advance to next Monday (7 days ahead if already Monday).
      const daysUntilMonday = ((1 - day + 7) % 7) || 7;
      next.setUTCDate(next.getUTCDate() + daysUntilMonday);
      next.setUTCHours(9, 0, 0, 0);
      return next.toISOString();
    }
  }
}

export function isSnoozeActive(snoozeUntil: string | null | undefined, now: Date = getAnchoredNow()): boolean {
  if (!snoozeUntil) return false;
  return new Date(snoozeUntil).getTime() > now.getTime();
}

