import type { Request, SegmentId } from "@/lib/types";
import { getAnchoredNow, hoursFromNow } from "@/lib/utils/time";
import { isSnoozeActive } from "./snooze";

export interface SegmentContext {
  currentUserId: string;
  now: Date;
}

/**
 * Predicate per segment. "all" excludes archived and actively-snoozed items.
 * "snoozed" shows only currently-snoozed items. "archived" shows only archived.
 */
export type SegmentPredicate = (req: Request, ctx: SegmentContext) => boolean;

function isArchived(r: Request): boolean {
  return r.isArchived ?? false;
}

function isRead(r: Request): boolean {
  return r.isRead ?? false;
}

export const segmentPredicates: Readonly<Record<SegmentId, SegmentPredicate>> = {
  all: (r, ctx) => !isArchived(r) && !isSnoozeActive(r.snoozeUntil, ctx.now),
  unread: (r, ctx) =>
    !isArchived(r) && !isSnoozeActive(r.snoozeUntil, ctx.now) && !isRead(r),
  assigned_me: (r, ctx) =>
    !isArchived(r) &&
    !isSnoozeActive(r.snoozeUntil, ctx.now) &&
    r.assigneeId === ctx.currentUserId,
  overdue: (r, ctx) =>
    !isArchived(r) &&
    !isSnoozeActive(r.snoozeUntil, ctx.now) &&
    hoursFromNow(r.slaDueAt) < 0,
  urgent: (r, ctx) =>
    !isArchived(r) &&
    !isSnoozeActive(r.snoozeUntil, ctx.now) &&
    r.priority === "urgent",
  snoozed: (r, ctx) => !isArchived(r) && isSnoozeActive(r.snoozeUntil, ctx.now),
  archived: (r) => isArchived(r),
};

export function filterBySegment(
  requests: readonly Request[],
  segmentId: SegmentId,
  ctx: Partial<SegmentContext> & { currentUserId: string },
): Request[] {
  const resolved: SegmentContext = {
    currentUserId: ctx.currentUserId,
    now: ctx.now ?? getAnchoredNow(),
  };
  const predicate = segmentPredicates[segmentId];
  return requests.filter((r) => predicate(r, resolved));
}

export function countBySegment(
  requests: readonly Request[],
  segmentId: SegmentId,
  ctx: Partial<SegmentContext> & { currentUserId: string },
): number {
  return filterBySegment(requests, segmentId, ctx).length;
}

