export interface MatchRange {
  start: number;
  end: number;
}

export interface MatchResult {
  matched: boolean;
  ranges: readonly MatchRange[];
}

/** Case-insensitive substring match with highlight ranges for the first hit. */
export function fuzzyMatch(query: string, text: string): MatchResult {
  const q = query.trim().toLowerCase();
  if (q.length === 0) {
    return { matched: true, ranges: [] };
  }
  const lower = text.toLowerCase();
  const idx = lower.indexOf(q);
  if (idx === -1) {
    return { matched: false, ranges: [] };
  }
  return {
    matched: true,
    ranges: [{ start: idx, end: idx + q.length }],
  };
}

export function highlightSegments(
  text: string,
  ranges: readonly MatchRange[],
): Array<{ text: string; highlight: boolean }> {
  if (ranges.length === 0) return [{ text, highlight: false }];
  const segments: Array<{ text: string; highlight: boolean }> = [];
  let cursor = 0;
  for (const range of ranges) {
    if (range.start > cursor) {
      segments.push({ text: text.slice(cursor, range.start), highlight: false });
    }
    segments.push({ text: text.slice(range.start, range.end), highlight: true });
    cursor = range.end;
  }
  if (cursor < text.length) {
    segments.push({ text: text.slice(cursor), highlight: false });
  }
  return segments;
}

