import type { SegmentId } from "@/lib/types";

export const STORAGE_KEY = "clientloop.inbox.v1";

export interface InboxPersistedState {
  readIds: readonly string[];
  unreadIds: readonly string[];
  archivedIds: readonly string[];
  unarchivedIds: readonly string[];
  snoozeMap: Readonly<Record<string, string | null>>;
  lastSegmentId: SegmentId;
  statusOverrides: Readonly<Record<string, string>>;
  priorityOverrides: Readonly<Record<string, string>>;
  assigneeOverrides: Readonly<Record<string, string>>;
}

export const EMPTY_PERSISTED: InboxPersistedState = {
  readIds: [],
  unreadIds: [],
  archivedIds: [],
  unarchivedIds: [],
  snoozeMap: {},
  lastSegmentId: "all",
  statusOverrides: {},
  priorityOverrides: {},
  assigneeOverrides: {},
};

function isSegmentId(value: unknown): value is SegmentId {
  return (
    value === "all" ||
    value === "unread" ||
    value === "assigned_me" ||
    value === "overdue" ||
    value === "urgent" ||
    value === "snoozed" ||
    value === "archived"
  );
}

function coerceStringArray(value: unknown): readonly string[] {
  if (!Array.isArray(value)) return [];
  return value.filter((v): v is string => typeof v === "string");
}

function coerceStringRecord(value: unknown): Readonly<Record<string, string>> {
  if (!value || typeof value !== "object") return {};
  const out: Record<string, string> = {};
  for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
    if (typeof v === "string") out[k] = v;
  }
  return out;
}

function coerceNullableStringRecord(
  value: unknown,
): Readonly<Record<string, string | null>> {
  if (!value || typeof value !== "object") return {};
  const out: Record<string, string | null> = {};
  for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
    if (typeof v === "string" || v === null) out[k] = v;
  }
  return out;
}

export function loadInboxPersistedState(): InboxPersistedState {
  if (typeof window === "undefined") return EMPTY_PERSISTED;
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return EMPTY_PERSISTED;
    const parsed: unknown = JSON.parse(raw);
    if (!parsed || typeof parsed !== "object") return EMPTY_PERSISTED;
    const obj = parsed as Record<string, unknown>;
    return {
      readIds: coerceStringArray(obj.readIds),
      unreadIds: coerceStringArray(obj.unreadIds),
      archivedIds: coerceStringArray(obj.archivedIds),
      unarchivedIds: coerceStringArray(obj.unarchivedIds),
      snoozeMap: coerceNullableStringRecord(obj.snoozeMap),
      lastSegmentId: isSegmentId(obj.lastSegmentId) ? obj.lastSegmentId : "all",
      statusOverrides: coerceStringRecord(obj.statusOverrides),
      priorityOverrides: coerceStringRecord(obj.priorityOverrides),
      assigneeOverrides: coerceStringRecord(obj.assigneeOverrides),
    };
  } catch {
    return EMPTY_PERSISTED;
  }
}

export function saveInboxPersistedState(state: InboxPersistedState): void {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  } catch {
    // quota exceeded or private mode — silently ignore
  }
}

