import type {
  InboxComment,
  Priority,
  Request,
  RequestStatus,
  SegmentId,
  TimelineEvent,
  TimelineEventType,
} from "@/lib/types";
import { getAnchoredNow } from "@/lib/utils/time";
import type { InboxPersistedState } from "./persistence";

export type InboxView = "list" | "kanban";

export interface InboxFilters {
  search: string;
  clientId: string | "all";
  tag: string | "all";
}

export interface InboxState {
  requests: readonly Request[];
  timeline: Readonly<Record<string, readonly TimelineEvent[]>>;
  comments: Readonly<Record<string, readonly InboxComment[]>>;
  segmentId: SegmentId;
  filters: InboxFilters;
  selectedRequestId: string | null;
  bulkSelection: ReadonlySet<string>;
  view: InboxView;
  paletteOpen: boolean;
  helpOpen: boolean;
  snoozeTargetId: string | null;
  hydrated: boolean;
  currentUserId: string;
}

export const DEFAULT_FILTERS: InboxFilters = {
  search: "",
  clientId: "all",
  tag: "all",
};

export interface InboxInitArgs {
  requests: readonly Request[];
  timeline: Readonly<Record<string, readonly TimelineEvent[]>>;
  comments: Readonly<Record<string, readonly InboxComment[]>>;
  currentUserId: string;
}

export function createInitialInboxState(args: InboxInitArgs): InboxState {
  return {
    requests: args.requests,
    timeline: args.timeline,
    comments: args.comments,
    segmentId: "all",
    filters: DEFAULT_FILTERS,
    selectedRequestId: null,
    bulkSelection: new Set<string>(),
    view: "list",
    paletteOpen: false,
    helpOpen: false,
    snoozeTargetId: null,
    hydrated: false,
    currentUserId: args.currentUserId,
  };
}

export type InboxAction =
  | { type: "HYDRATE"; payload: InboxPersistedState }
  | { type: "SET_VIEW"; view: InboxView }
  | { type: "SET_SEGMENT"; segmentId: SegmentId }
  | { type: "SET_FILTERS"; filters: Partial<InboxFilters> }
  | { type: "SELECT_REQUEST"; id: string | null }
  | { type: "TOGGLE_ROW_SELECTED"; id: string }
  | { type: "SELECT_ALL"; ids: readonly string[] }
  | { type: "CLEAR_SELECTION" }
  | { type: "MARK_READ"; id: string; read: boolean }
  | { type: "TOGGLE_ARCHIVE"; id: string }
  | { type: "ARCHIVE_MANY"; ids: readonly string[]; archived: boolean }
  | { type: "SNOOZE"; id: string; until: string | null }
  | { type: "SNOOZE_MANY"; ids: readonly string[]; until: string | null }
  | { type: "SET_STATUS"; id: string; status: RequestStatus }
  | { type: "SET_PRIORITY"; id: string; priority: Priority }
  | { type: "SET_ASSIGNEE"; id: string; assigneeId: string }
  | { type: "BULK_SET_STATUS"; ids: readonly string[]; status: RequestStatus }
  | { type: "BULK_SET_PRIORITY"; ids: readonly string[]; priority: Priority }
  | { type: "BULK_SET_ASSIGNEE"; ids: readonly string[]; assigneeId: string }
  | { type: "ADD_COMMENT"; requestId: string; body: string; authorId: string }
  | { type: "SET_PALETTE_OPEN"; open: boolean }
  | { type: "SET_HELP_OPEN"; open: boolean }
  | { type: "SET_SNOOZE_TARGET"; id: string | null };

function nowIso(): string {
  return getAnchoredNow().toISOString();
}

function updateRequest(
  state: InboxState,
  id: string,
  update: (r: Request) => Request,
): InboxState {
  const next = state.requests.map((r) => (r.id === id ? update(r) : r));
  return { ...state, requests: next };
}

function updateManyRequests(
  state: InboxState,
  ids: readonly string[],
  update: (r: Request) => Request,
): InboxState {
