}

function appendTimeline(
  state: InboxState,
  requestId: string,
  type: TimelineEventType,
  meta?: Readonly<Record<string, string>>,
): InboxState {
  const existing = state.timeline[requestId] ?? [];
  const event: TimelineEvent = {
    id: `tl-${requestId}-${existing.length + 1}-${Date.now()}`,
    requestId,
    type,
    actorId: state.currentUserId,
    timestamp: nowIso(),
    meta,
  };
