    ...state,
    timeline: {
      ...state.timeline,
      [requestId]: [...existing, event],
    },
  };
}

function applyHydration(
  state: InboxState,
  payload: InboxPersistedState,
): InboxState {
  const readSet = new Set(payload.readIds);
  const unreadSet = new Set(payload.unreadIds);
  const archivedSet = new Set(payload.archivedIds);
  const unarchivedSet = new Set(payload.unarchivedIds);

  const requests = state.requests.map((r) => {
    const snoozeOverride = payload.snoozeMap[r.id];
    const statusOverride = payload.statusOverrides[r.id];
    const priorityOverride = payload.priorityOverrides[r.id];
    const assigneeOverride = payload.assigneeOverrides[r.id];

    let isRead = r.isRead ?? false;
    if (readSet.has(r.id)) isRead = true;
    if (unreadSet.has(r.id)) isRead = false;

    let isArchived = r.isArchived ?? false;
    if (archivedSet.has(r.id)) isArchived = true;
    if (unarchivedSet.has(r.id)) isArchived = false;

    const next: Request = {
      ...r,
      isRead,
      isArchived,
      snoozeUntil:
        snoozeOverride !== undefined ? snoozeOverride : r.snoozeUntil ?? null,
      status: isRequestStatus(statusOverride) ? statusOverride : r.status,
      priority: isPriority(priorityOverride) ? priorityOverride : r.priority,
      assigneeId: assigneeOverride ?? r.assigneeId,
    };
    return next;
  });

  return {
    ...state,
    requests,
    segmentId: payload.lastSegmentId,
    hydrated: true,
  };
}

function isRequestStatus(value: unknown): value is RequestStatus {
  return (
    value === "backlog" ||
    value === "in_progress" ||
    value === "review" ||
    value === "delivered"
  );
}

function isPriority(value: unknown): value is Priority {
  return value === "low" || value === "normal" || value === "high" || value === "urgent";
}

export function inboxReducer(state: InboxState, action: InboxAction): InboxState {
  switch (action.type) {
    case "HYDRATE":
      return applyHydration(state, action.payload);

    case "SET_VIEW":
      return { ...state, view: action.view };

    case "SET_SEGMENT":
      return {
        ...state,
        segmentId: action.segmentId,
        selectedRequestId: null,
        bulkSelection: new Set(),
      };

    case "SET_FILTERS":
      return {
        ...state,
        filters: { ...state.filters, ...action.filters },
      };

    case "SELECT_REQUEST": {
      if (action.id === null) {
        return { ...state, selectedRequestId: null };
      }
      // Auto-mark read when opening
      const next = updateRequest(state, action.id, (r) =>
        r.isRead ? r : { ...r, isRead: true, lastActivityAt: r.lastActivityAt ?? nowIso() },
      );
      return { ...next, selectedRequestId: action.id };
    }

    case "TOGGLE_ROW_SELECTED": {
      const next = new Set(state.bulkSelection);
      if (next.has(action.id)) next.delete(action.id);
      else next.add(action.id);
      return { ...state, bulkSelection: next };
    }

    case "SELECT_ALL": {
      return { ...state, bulkSelection: new Set(action.ids) };
    }

    case "CLEAR_SELECTION":
      return { ...state, bulkSelection: new Set() };

    case "MARK_READ":
      return updateRequest(state, action.id, (r) => ({ ...r, isRead: action.read }));

    case "TOGGLE_ARCHIVE": {
      const target = state.requests.find((r) => r.id === action.id);
      if (!target) return state;
      const nextArchived = !(target.isArchived ?? false);
      const next = updateRequest(state, action.id, (r) => ({
        ...r,
        isArchived: nextArchived,
        lastActivityAt: nowIso(),
      }));
      return appendTimeline(next, action.id, nextArchived ? "archived" : "unarchived");
    }

    case "ARCHIVE_MANY": {
      const next = updateManyRequests(state, action.ids, (r) => ({
        ...r,
        isArchived: action.archived,
        lastActivityAt: nowIso(),
      }));
      return {
        ...next,
        bulkSelection: new Set(),
      };
    }

    case "SNOOZE": {
      const next = updateRequest(state, action.id, (r) => ({
        ...r,
        snoozeUntil: action.until,
        lastActivityAt: nowIso(),
      }));
      return appendTimeline(
        next,
        action.id,
        action.until ? "snoozed" : "unsnoozed",
        action.until ? { until: action.until } : undefined,
      );
    }

    case "SNOOZE_MANY": {
      const next = updateManyRequests(state, action.ids, (r) => ({
        ...r,
        snoozeUntil: action.until,
        lastActivityAt: nowIso(),
      }));
      return { ...next, bulkSelection: new Set() };
    }

    case "SET_STATUS": {
      const target = state.requests.find((r) => r.id === action.id);
      if (!target || target.status === action.status) return state;
      const next = updateRequest(state, action.id, (r) => ({
        ...r,
        status: action.status,
        lastActivityAt: nowIso(),
      }));
      return appendTimeline(next, action.id, "status_changed", {
        from: target.status,
        to: action.status,
      });
    }

    case "SET_PRIORITY": {
      const target = state.requests.find((r) => r.id === action.id);
      if (!target || target.priority === action.priority) return state;
      const next = updateRequest(state, action.id, (r) => ({
        ...r,
        priority: action.priority,
        lastActivityAt: nowIso(),
      }));
      return appendTimeline(next, action.id, "priority_changed", {
        from: target.priority,
        to: action.priority,
      });
    }

    case "SET_ASSIGNEE": {
      const target = state.requests.find((r) => r.id === action.id);
      if (!target || target.assigneeId === action.assigneeId) return state;
      const next = updateRequest(state, action.id, (r) => ({
        ...r,
        assigneeId: action.assigneeId,
        lastActivityAt: nowIso(),
      }));
      return appendTimeline(next, action.id, "assignee_changed", {
        from: target.assigneeId,
        to: action.assigneeId,
      });
    }

    case "BULK_SET_STATUS": {
      const next = updateManyRequests(state, action.ids, (r) => ({
        ...r,
        status: action.status,
        lastActivityAt: nowIso(),
      }));
      return { ...next, bulkSelection: new Set() };
    }

    case "BULK_SET_PRIORITY": {
      const next = updateManyRequests(state, action.ids, (r) => ({
        ...r,
        priority: action.priority,
        lastActivityAt: nowIso(),
      }));
      return { ...next, bulkSelection: new Set() };
    }

    case "BULK_SET_ASSIGNEE": {
      const next = updateManyRequests(state, action.ids, (r) => ({
        ...r,
        assigneeId: action.assigneeId,
        lastActivityAt: nowIso(),
      }));
      return { ...next, bulkSelection: new Set() };
    }

    case "ADD_COMMENT": {
      const existing = state.comments[action.requestId] ?? [];
      const comment: InboxComment = {
        id: `cm-${action.requestId}-${existing.length + 1}-${Date.now()}`,
        requestId: action.requestId,
        authorId: action.authorId,
        body: action.body,
        createdAt: nowIso(),
      };
      const nextState: InboxState = {
        ...state,
        comments: {
          ...state.comments,
          [action.requestId]: [...existing, comment],
        },
      };
      const withActivity = updateRequest(nextState, action.requestId, (r) => ({
        ...r,
        lastActivityAt: nowIso(),
      }));
      return appendTimeline(withActivity, action.requestId, "comment_added");
    }

    case "SET_PALETTE_OPEN":
      return { ...state, paletteOpen: action.open };

    case "SET_HELP_OPEN":
      return { ...state, helpOpen: action.open };

    case "SET_SNOOZE_TARGET":
      return { ...state, snoozeTargetId: action.id };
  }
}

/**
 * Derive a persisted snapshot from the live state. Only stores deltas —
 * if a user reverts a field, the override is kept but the mock's default wins
 * on next load via the hydrate merge.
 */
export function toPersistedState(
  state: InboxState,
  baseline: readonly Request[],
): InboxPersistedState {
  const readIds: string[] = [];
  const unreadIds: string[] = [];
  const archivedIds: string[] = [];
  const unarchivedIds: string[] = [];
  const snoozeMap: Record<string, string | null> = {};
  const statusOverrides: Record<string, string> = {};
  const priorityOverrides: Record<string, string> = {};
  const assigneeOverrides: Record<string, string> = {};

  const baselineById = new Map(baseline.map((r) => [r.id, r]));

  for (const r of state.requests) {
    const base = baselineById.get(r.id);
    if (!base) continue;
    if ((r.isRead ?? false) !== (base.isRead ?? false)) {
      if (r.isRead) readIds.push(r.id);
      else unreadIds.push(r.id);
    }
