    if (r.status !== base.status) statusOverrides[r.id] = r.status;
    if (r.priority !== base.priority) priorityOverrides[r.id] = r.priority;
    if (r.assigneeId !== base.assigneeId) assigneeOverrides[r.id] = r.assigneeId;
  }

  return {
    readIds,
    unreadIds,
    archivedIds,
    unarchivedIds,
    snoozeMap,
    lastSegmentId: state.segmentId,
    statusOverrides,
    priorityOverrides,
    assigneeOverrides,
  };
}

