"use client";

import { useEffect } from "react";

export interface InboxHotkeyHandlers {
  onNavigateDown: () => void;
  onNavigateUp: () => void;
  onOpen: () => void;
  onArchive: () => void;
  onSnooze: () => void;
  onAssign: () => void;
  onSetStatus: (slot: 1 | 2 | 3 | 4) => void;
  onOpenPalette: () => void;
  onShowHelp: () => void;
  onEscape: () => void;
  disabled?: boolean;
  paletteOpen?: boolean;
}

function isEditableTarget(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false;
  const tag = target.tagName;
  if (tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT") return true;
  if (target.isContentEditable) return true;
  return false;
}

export function useInboxHotkeys(handlers: InboxHotkeyHandlers): void {
  useEffect(() => {
    if (handlers.disabled) return;

    const onKeyDown = (event: KeyboardEvent) => {
      const inEditable = isEditableTarget(event.target);
      const mod = event.metaKey || event.ctrlKey;

      // Cmd/Ctrl+K always opens the palette, even from inputs.
      if (mod && event.key.toLowerCase() === "k") {
        event.preventDefault();
        handlers.onOpenPalette();
        return;
      }

      if (event.key === "Escape") {
        handlers.onEscape();
        return;
      }

      // Everything below is suppressed while palette is open or focus is in a field.
      if (handlers.paletteOpen || inEditable) return;

      switch (event.key) {
        case "j":
        case "ArrowDown":
          event.preventDefault();
          handlers.onNavigateDown();
          return;
        case "k":
        case "ArrowUp":
          event.preventDefault();
          handlers.onNavigateUp();
          return;
        case "Enter":
          handlers.onOpen();
          return;
        case "e":
          handlers.onArchive();
          return;
        case "s":
          handlers.onSnooze();
          return;
        case "a":
          handlers.onAssign();
          return;
        case "1":
        case "2":
        case "3":
        case "4": {
          const slot = Number(event.key) as 1 | 2 | 3 | 4;
          handlers.onSetStatus(slot);
          return;
        }
        case "?":
          handlers.onShowHelp();
          return;
        default:
          return;
      }
    };

    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [handlers]);
}

