"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useReducer,
  useRef,
  type ReactNode,
} from "react";
import type {
  Assignee,
  Client,
  Request,
  SavedSegment,
  SegmentId,
} from "@/lib/types";
import {
  createInitialInboxState,
  inboxReducer,
  toPersistedState,
  type InboxAction,
  type InboxState,
} from "@/lib/inbox/reducer";
import {
  EMPTY_PERSISTED,
  loadInboxPersistedState,
  saveInboxPersistedState,
  type InboxPersistedState,
} from "@/lib/inbox/persistence";
import { filterBySegment } from "@/lib/inbox/segments";
import { fuzzyMatch } from "@/lib/inbox/search";
import { getAnchoredNow } from "@/lib/utils/time";

export interface InboxProviderProps {
  children: ReactNode;
  requests: readonly Request[];
  timeline: Readonly<Record<string, readonly import("@/lib/types").TimelineEvent[]>>;
  comments: Readonly<Record<string, readonly import("@/lib/types").InboxComment[]>>;
  clients: readonly Client[];
  assignees: readonly Assignee[];
  segments: readonly SavedSegment[];
  currentUser: Assignee;
}

export interface InboxContextValue {
  state: InboxState;
  dispatch: (action: InboxAction) => void;
  clients: readonly Client[];
  assignees: readonly Assignee[];
  segments: readonly SavedSegment[];
  currentUser: Assignee;
  visibleRequests: readonly Request[];
  segmentCounts: Readonly<Record<SegmentId, number>>;
  selectedRequest: Request | null;
  clientById: (id: string) => Client | undefined;
  assigneeById: (id: string) => Assignee | undefined;
}

const InboxContext = createContext<InboxContextValue | null>(null);

export function InboxProvider({
  children,
  requests,
  timeline,
  comments,
  clients,
  assignees,
  segments,
  currentUser,
}: InboxProviderProps) {
  const baselineRef = useRef<readonly Request[]>(requests);

  const [state, dispatch] = useReducer(
    inboxReducer,
    { requests, timeline, comments, currentUserId: currentUser.id },
    createInitialInboxState,
  );

  // Hydrate from localStorage once on mount.
  useEffect(() => {
    const persisted = loadInboxPersistedState();
    dispatch({ type: "HYDRATE", payload: persisted });
  }, []);

  // Persist deltas (debounced) whenever state drifts from baseline.
  useEffect(() => {
    if (!state.hydrated) return;
    const handle = window.setTimeout(() => {
      const snapshot = toPersistedState(state, baselineRef.current);
      saveInboxPersistedState(snapshot);
    }, 300);
    return () => window.clearTimeout(handle);
  }, [state]);

  const now = useMemo(() => getAnchoredNow(), []);

  const segmentFiltered = useMemo(() => {
    return filterBySegment(state.requests, state.segmentId, {
      currentUserId: currentUser.id,
      now,
    });
  }, [state.requests, state.segmentId, currentUser.id, now]);

  const visibleRequests = useMemo(() => {
    const { search, clientId, tag } = state.filters;
    return segmentFiltered.filter((req) => {
      if (clientId !== "all" && req.clientId !== clientId) return false;
      if (tag !== "all" && !req.tags.includes(tag)) return false;
      if (search.trim().length > 0) {
        const match =
          fuzzyMatch(search, req.title).matched ||
          fuzzyMatch(search, req.rawMessage).matched;
        if (!match) return false;
      }
      return true;
    });
  }, [segmentFiltered, state.filters]);

  const segmentCounts = useMemo(() => {
    const counts: Record<SegmentId, number> = {
      all: 0,
      unread: 0,
      assigned_me: 0,
      overdue: 0,
      urgent: 0,
      snoozed: 0,
      archived: 0,
    };
    for (const segment of segments) {
      counts[segment.id] = filterBySegment(state.requests, segment.id, {
        currentUserId: currentUser.id,
        now,
      }).length;
    }
    return counts;
  }, [state.requests, segments, currentUser.id, now]);

  const selectedRequest = useMemo(() => {
    if (!state.selectedRequestId) return null;
    return state.requests.find((r) => r.id === state.selectedRequestId) ?? null;
  }, [state.requests, state.selectedRequestId]);

  const clientMap = useMemo(() => new Map(clients.map((c) => [c.id, c])), [clients]);
  const assigneeMap = useMemo(
    () => new Map(assignees.map((a) => [a.id, a])),
    [assignees],
  );

  const clientById = useCallback((id: string) => clientMap.get(id), [clientMap]);
  const assigneeById = useCallback(
    (id: string) => assigneeMap.get(id),
    [assigneeMap],
  );

  const value: InboxContextValue = {
    state,
    dispatch,
    clients,
    assignees,
    segments,
    currentUser,
    visibleRequests,
    segmentCounts,
    selectedRequest,
    clientById,
    assigneeById,
  };

  return <InboxContext.Provider value={value}>{children}</InboxContext.Provider>;
}

export function useInboxState(): InboxContextValue {
  const ctx = useContext(InboxContext);
  if (!ctx) {
    throw new Error("useInboxState must be used inside <InboxProvider>");
  }
  return ctx;
}

// Re-export persistence types so tests can import from one place.
export type { InboxPersistedState };
export { EMPTY_PERSISTED };

