"use client";

import { usePathname } from "next/navigation";
import Link from "next/link";
import { Bell, Search } from "lucide-react";

import { SidebarTrigger } from "@/components/ui/sidebar";
import { Separator } from "@/components/ui/separator";
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

const SEGMENT_LABELS: Record<string, string> = {
  dashboard: "Dashboard",
  inbox: "Inbox",
  clients: "Clients",
  services: "Services",
  settings: "Settings",
};

function getSegmentLabel(segment: string): string {
  const label = SEGMENT_LABELS[segment];
  if (label !== undefined) return label;
  return segment.charAt(0).toUpperCase() + segment.slice(1);
}

export function AppHeader() {
  const pathname = usePathname();

  // Build breadcrumb segments — skip empty strings, max 2
  const segments = pathname.split("/").filter(Boolean).slice(0, 2);

  const firstSegment = segments[0] ?? "";
  const secondSegment = segments[1] ?? "";

  return (
    <header className="sticky top-0 z-30 flex h-16 items-center gap-3 border-b bg-background/90 backdrop-blur-md px-4 md:px-6 shadow-xs">
      {/* Mobile sidebar trigger */}
      <SidebarTrigger className="md:hidden" />
      <Separator orientation="vertical" className="h-4 md:hidden" />

      {/* Breadcrumb */}
      <Breadcrumb>
        <BreadcrumbList>
          {segments.length === 0 ? (
            <BreadcrumbItem>
              <BreadcrumbPage>Home</BreadcrumbPage>
            </BreadcrumbItem>
          ) : segments.length === 1 ? (
            <BreadcrumbItem>
              <BreadcrumbPage>{getSegmentLabel(firstSegment)}</BreadcrumbPage>
            </BreadcrumbItem>
          ) : (
            <>
              <BreadcrumbItem>
                <BreadcrumbLink render={<Link href={`/${firstSegment}`} />}>
                  {getSegmentLabel(firstSegment)}
                </BreadcrumbLink>
              </BreadcrumbItem>
              <BreadcrumbSeparator />
              <BreadcrumbItem>
                <BreadcrumbPage>{getSegmentLabel(secondSegment)}</BreadcrumbPage>
              </BreadcrumbItem>
            </>
          )}
        </BreadcrumbList>
      </Breadcrumb>

      {/* Right side actions */}
      <div className="ml-auto flex items-center gap-2">
        {/* Search */}
        <div className="relative hidden sm:block">
          <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 size-3.5 text-muted-foreground pointer-events-none" />
          <Input
            placeholder="Search requests, clients…"
            className="w-48 md:w-64 pl-8 h-9 text-sm bg-muted/70 border-transparent focus-visible:border-input focus-visible:bg-background transition-colors"
          />
        </div>

        {/* Notifications */}
        <Button
          variant="ghost"
          size="icon"
          className="relative size-8"
          aria-label="Notifications"
        >
          <Bell className="size-4" />
          <span
            className="absolute top-1 right-1 size-2.5 rounded-full bg-destructive ring-2 ring-background"
            aria-hidden="true"
          />
        </Button>

        {/* User dropdown */}
        <DropdownMenu>
          <DropdownMenuTrigger
            render={
              <button
                type="button"
                className="flex items-center gap-1.5 rounded-full focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              />
            }
          >
            <Avatar className="size-7">
              <AvatarImage
                src="https://i.pravatar.cc/128?u=a01"
                alt="Priya Sharma"
              />
              <AvatarFallback className="text-xs">PS</AvatarFallback>
            </Avatar>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-48" sideOffset={6}>
            <DropdownMenuItem render={<Link href="/settings/billing" />}>
              Billing
            </DropdownMenuItem>
            <DropdownMenuItem render={<Link href="/settings/team" />}>
              Team
            </DropdownMenuItem>
            <DropdownMenuSeparator />
            <DropdownMenuItem className="text-destructive focus:text-destructive">
              Log out
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    </header>
  );
}
import { AppSidebar } from "@/components/shell/app-sidebar";
import { AppHeader } from "@/components/shell/app-header";
import { SidebarInset, SidebarProvider } from "@/components/ui/sidebar";

export default function DashboardLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <SidebarProvider>
      <AppSidebar />
      <SidebarInset className="h-svh overflow-y-auto">
        <AppHeader />
        <main className="flex-1 px-4 py-8 md:px-8 md:py-10 max-w-[1360px] w-full mx-auto">
          {children}
        </main>
      </SidebarInset>
    </SidebarProvider>
  );
}

