"use client";

import { Command, HelpCircle, KanbanSquare, List, Search, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";
import { useInboxState } from "./inbox-provider";

export function InboxTopbar() {
  const { state, dispatch, visibleRequests } = useInboxState();
  const { view, filters } = state;

  return (
    <div className="flex items-center gap-2 border-b border-border/60 bg-background/80 backdrop-blur-md px-4 py-2.5">
      {/* Search */}
      <div className="relative flex-1 min-w-0 max-w-md">
        <Search className="pointer-events-none absolute left-2.5 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground" />
        <Input
          value={filters.search}
          onChange={(event) =>
            dispatch({ type: "SET_FILTERS", filters: { search: event.target.value } })
          }
          placeholder="Search requests, clients, tags…"
          className="h-9 pl-8 pr-8 text-sm bg-muted/50 border-transparent focus-visible:bg-background focus-visible:border-input"
        />
        {filters.search.length > 0 ? (
          <button
            type="button"
            aria-label="Clear search"
            onClick={() => dispatch({ type: "SET_FILTERS", filters: { search: "" } })}
            className="absolute right-2 top-1/2 -translate-y-1/2 rounded-sm p-0.5 text-muted-foreground hover:text-foreground transition-colors"
          >
            <X className="size-3.5" />
          </button>
        ) : null}
      </div>

      {/* Result count */}
      <span className="hidden md:inline text-xs text-muted-foreground tabular-nums">
        {visibleRequests.length} {visibleRequests.length === 1 ? "request" : "requests"}
      </span>

      <div className="ml-auto flex items-center gap-2">
        {/* Command palette hint */}
        <Button
          variant="outline"
          size="sm"
          onClick={() => dispatch({ type: "SET_PALETTE_OPEN", open: true })}
          className="hidden md:flex h-9 gap-1.5 text-xs text-muted-foreground"
        >
          <Command className="size-3.5" />
          <span>Command</span>
          <kbd className="ml-1 rounded bg-muted px-1.5 py-0.5 text-[10px] font-medium">
            ⌘K
          </kbd>
        </Button>

        {/* View toggle */}
        <div className="inline-flex h-9 items-center rounded-lg border bg-muted/40 p-0.5">
          <button
            type="button"
            aria-label="List view"
            aria-pressed={view === "list"}
            onClick={() => dispatch({ type: "SET_VIEW", view: "list" })}
            className={cn(
              "inline-flex h-8 items-center gap-1.5 rounded-md px-2.5 text-xs font-medium transition-all",
              view === "list"
                ? "bg-background text-foreground shadow-[var(--shadow-xs)]"
                : "text-muted-foreground hover:text-foreground",
            )}
          >
            <List className="size-3.5" />
            <span className="hidden sm:inline">List</span>
          </button>
          <button
            type="button"
            aria-label="Kanban view"
            aria-pressed={view === "kanban"}
            onClick={() => dispatch({ type: "SET_VIEW", view: "kanban" })}
            className={cn(
              "inline-flex h-8 items-center gap-1.5 rounded-md px-2.5 text-xs font-medium transition-all",
              view === "kanban"
                ? "bg-background text-foreground shadow-[var(--shadow-xs)]"
                : "text-muted-foreground hover:text-foreground",
            )}
          >
            <KanbanSquare className="size-3.5" />
            <span className="hidden sm:inline">Kanban</span>
          </button>
        </div>

        {/* Help */}
        <Button
          variant="ghost"
          size="icon"
          onClick={() => dispatch({ type: "SET_HELP_OPEN", open: true })}
          aria-label="Keyboard shortcuts"
          className="size-9"
        >
          <HelpCircle className="size-4" />
        </Button>
      </div>
    </div>
  );
}

