"use client";

import type { LucideIcon } from "lucide-react";
import {
  Archive,
  Flame,
  Inbox,
  Mail,
  Moon,
  TriangleAlert,
  User,
} from "lucide-react";
import type { SegmentIconName } from "@/lib/types";
import { cn } from "@/lib/utils";
import { useInboxState } from "./inbox-provider";

const ICON_MAP: Record<SegmentIconName, LucideIcon> = {
  inbox: Inbox,
  mail: Mail,
  user: User,
  "alert-triangle": TriangleAlert,
  flame: Flame,
  moon: Moon,
  archive: Archive,
};

export function SegmentRail() {
  const { state, dispatch, segments, segmentCounts } = useInboxState();

  return (
    <aside
      aria-label="Inbox segments"
      className="hidden md:flex flex-col border-r border-border/60 bg-sidebar/40"
    >
      <div className="flex items-center gap-2 px-4 py-4 xl:px-5">
        <div className="flex size-8 items-center justify-center rounded-lg bg-primary/10 text-primary">
          <Inbox className="size-4" />
        </div>
        <div className="hidden xl:flex flex-col">
          <span className="text-sm font-semibold tracking-tight">Inbox</span>
          <span className="text-[11px] text-muted-foreground">
            Triage & respond
          </span>
        </div>
      </div>

      <nav className="flex flex-1 flex-col gap-0.5 px-2 xl:px-3 pb-4">
        {segments.map((segment) => {
          const Icon = ICON_MAP[segment.iconName];
          const count = segmentCounts[segment.id];
          const isActive = state.segmentId === segment.id;
          return (
            <button
              key={segment.id}
              type="button"
              onClick={() => dispatch({ type: "SET_SEGMENT", segmentId: segment.id })}
              aria-pressed={isActive}
              title={segment.label}
              className={cn(
                "group relative flex h-9 items-center gap-2.5 rounded-lg px-2 xl:px-2.5 text-left transition-all",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1",
                isActive
                  ? "bg-sidebar-accent text-sidebar-primary ring-1 ring-primary/10"
                  : "text-sidebar-foreground/80 hover:bg-sidebar-accent/60 hover:text-sidebar-foreground",
              )}
            >
              <Icon
                className={cn(
                  "size-4 shrink-0 transition-colors",
                  isActive ? "text-primary" : "text-muted-foreground",
                )}
              />
              <span
                className={cn(
                  "hidden xl:block flex-1 truncate text-[13px]",
                  isActive ? "font-medium" : "font-normal",
                )}
              >
                {segment.label}
              </span>
              <span
                className={cn(
                  "hidden xl:inline tabular-nums text-[11px]",
                  isActive ? "text-primary" : "text-muted-foreground",
                )}
              >
                {count}
              </span>
            </button>
          );
        })}
      </nav>
    </aside>
  );
}

