"use client";

import { Inbox, Sparkles, SearchX } from "lucide-react";
import { Button } from "@/components/ui/button";
import type { SegmentId } from "@/lib/types";

interface ListEmptyStateProps {
  segmentId: SegmentId;
  hasActiveFilters: boolean;
  onClearFilters: () => void;
}

export function ListEmptyState({
  segmentId,
  hasActiveFilters,
  onClearFilters,
}: ListEmptyStateProps) {
  if (hasActiveFilters) {
    return (
      <div className="flex h-full flex-col items-center justify-center gap-4 px-8 text-center">
        <div className="flex size-12 items-center justify-center rounded-full bg-muted text-muted-foreground">
          <SearchX className="size-5" />
        </div>
        <div className="space-y-1">
          <p className="text-sm font-semibold">No matching requests</p>
          <p className="text-xs text-muted-foreground max-w-sm">
            Try clearing your search or switching segments.
          </p>
        </div>
        <Button variant="outline" size="sm" onClick={onClearFilters}>
          Clear filters
        </Button>
      </div>
    );
  }

  // Celebratory inbox zero — only for segments where empty means "you did it"
  const celebratory: readonly SegmentId[] = [
    "all",
    "unread",
    "assigned_me",
    "overdue",
    "urgent",
  ];
  if (celebratory.includes(segmentId)) {
    return (
      <div className="relative flex h-full flex-col items-center justify-center gap-4 px-8 text-center overflow-hidden">
        <div
          aria-hidden="true"
          className="absolute inset-0 bg-[radial-gradient(circle_at_30%_20%,color-mix(in_oklch,var(--primary)_12%,transparent),transparent_60%)]"
        />
        <div className="relative flex size-14 items-center justify-center rounded-2xl bg-primary/10 text-primary animate-[fade-in-up_var(--duration-base)_var(--ease-out-expo)]">
          <Sparkles className="size-6" />
        </div>
        <div className="relative space-y-1">
          <p className="text-base font-semibold tracking-tight">Inbox zero</p>
          <p className="text-xs text-muted-foreground max-w-sm">
            Nothing needs your attention here. Take a breath or move on to another segment.
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-full flex-col items-center justify-center gap-4 px-8 text-center">
      <div className="flex size-12 items-center justify-center rounded-full bg-muted text-muted-foreground">
        <Inbox className="size-5" />
      </div>
      <p className="text-sm text-muted-foreground">No requests in this segment.</p>
    </div>
  );
}

