"use client";

import { useEffect, useRef, useState } from "react";
import { ScrollArea } from "@/components/ui/scroll-area";
import type { Request } from "@/lib/types";
import { ListEmptyState } from "./list-empty-state";
import { RequestRow } from "./request-row";
import { useInboxState } from "./inbox-provider";

interface RequestListProps {
  focusedIndex: number;
  onFocusIndex: (index: number) => void;
}

export function RequestList({ focusedIndex, onFocusIndex }: RequestListProps) {
  const { state, dispatch, visibleRequests } = useInboxState();

  const hasActiveFilters =
    state.filters.search.trim().length > 0 ||
    state.filters.clientId !== "all" ||
    state.filters.tag !== "all";

  const containerRef = useRef<HTMLDivElement>(null);

  // Keep focused row in view when j/k navigates off-screen.
  useEffect(() => {
    if (focusedIndex < 0) return;
    const row = containerRef.current?.querySelector<HTMLElement>(
      `[data-row-index="${focusedIndex}"]`,
    );
    row?.scrollIntoView({ block: "nearest" });
  }, [focusedIndex]);

  if (visibleRequests.length === 0) {
    return (
      <ListEmptyState
        segmentId={state.segmentId}
        hasActiveFilters={hasActiveFilters}
        onClearFilters={() => {
          dispatch({
            type: "SET_FILTERS",
            filters: { search: "", clientId: "all", tag: "all" },
          });
        }}
      />
    );
  }

  return (
    <ScrollArea className="h-full">
      <div ref={containerRef} role="list" aria-label="Requests">
        {visibleRequests.map((req: Request, index: number) => (
          <div key={req.id} data-row-index={index} role="listitem">
            <RequestRow
              request={req}
              index={index}
              isSelected={state.selectedRequestId === req.id}
              isFocused={focusedIndex === index}
              isBulkSelected={state.bulkSelection.has(req.id)}
              onFocus={onFocusIndex}
            />
          </div>
        ))}
      </div>
    </ScrollArea>
  );
}

