"use client";

import { toast } from "sonner";
import { Archive, Moon, User, X, Flag, CircleDot } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import type { Priority, RequestStatus } from "@/lib/types";
import { useInboxState } from "./inbox-provider";
import {
  PRIORITY_LABELS,
  PRIORITY_ORDER,
  STATUS_LABELS,
  STATUS_ORDER,
} from "@/lib/inbox/labels";
import { resolveSnoozeTime } from "@/lib/inbox/snooze";

export function BulkActionBar() {
  const { state, dispatch, assignees } = useInboxState();
  const selectedIds = Array.from(state.bulkSelection);
  const count = selectedIds.length;

  if (count === 0) return null;

  function bulkStatus(status: RequestStatus) {
    dispatch({ type: "BULK_SET_STATUS", ids: selectedIds, status });
    toast.success(`Moved ${count} to ${STATUS_LABELS[status]}`);
  }

  function bulkPriority(priority: Priority) {
    dispatch({ type: "BULK_SET_PRIORITY", ids: selectedIds, priority });
    toast.success(`Set ${count} to ${PRIORITY_LABELS[priority]}`);
  }

  function bulkAssign(assigneeId: string) {
    const assignee = assignees.find((a) => a.id === assigneeId);
    dispatch({ type: "BULK_SET_ASSIGNEE", ids: selectedIds, assigneeId });
    toast.success(`Assigned ${count} to ${assignee?.name ?? "teammate"}`);
  }

  function bulkArchive() {
    dispatch({ type: "ARCHIVE_MANY", ids: selectedIds, archived: true });
    toast.success(`Archived ${count} ${count === 1 ? "request" : "requests"}`);
  }

  function bulkSnooze() {
    const until = resolveSnoozeTime("tomorrow");
    dispatch({ type: "SNOOZE_MANY", ids: selectedIds, until });
    toast.success(`Snoozed ${count} until tomorrow`);
  }

  return (
    <div
      role="toolbar"
      aria-label="Bulk actions"
      className="fixed bottom-6 left-1/2 z-30 flex -translate-x-1/2 items-center gap-1 rounded-full border border-border/60 bg-background/95 backdrop-blur px-2 py-1.5 shadow-[var(--shadow-xl)] animate-[scale-in_var(--duration-base)_var(--ease-out-expo)]"
    >
      <div className="inline-flex items-center gap-2 rounded-full bg-primary/10 px-3 py-1 text-xs font-medium text-primary">
        <span className="size-1.5 rounded-full bg-primary" />
        {count} selected
      </div>

      <div className="mx-1 h-5 w-px bg-border/70" />

      {/* Status */}
      <DropdownMenu>
        <DropdownMenuTrigger
          render={
            <Button variant="ghost" size="sm" className="h-8 gap-1.5 text-xs">
              <CircleDot className="size-3.5" />
              Status
            </Button>
          }
        />
        <DropdownMenuContent align="center" sideOffset={8}>
          <DropdownMenuLabel>Change status</DropdownMenuLabel>
          <DropdownMenuSeparator />
          {STATUS_ORDER.map((status) => (
            <DropdownMenuItem key={status} onClick={() => bulkStatus(status)}>
              {STATUS_LABELS[status]}
            </DropdownMenuItem>
          ))}
        </DropdownMenuContent>
      </DropdownMenu>

      {/* Priority */}
      <DropdownMenu>
        <DropdownMenuTrigger
          render={
            <Button variant="ghost" size="sm" className="h-8 gap-1.5 text-xs">
              <Flag className="size-3.5" />
              Priority
            </Button>
          }
        />
        <DropdownMenuContent align="center" sideOffset={8}>
          <DropdownMenuLabel>Set priority</DropdownMenuLabel>
          <DropdownMenuSeparator />
          {PRIORITY_ORDER.map((priority) => (
            <DropdownMenuItem key={priority} onClick={() => bulkPriority(priority)}>
              {PRIORITY_LABELS[priority]}
            </DropdownMenuItem>
          ))}
        </DropdownMenuContent>
      </DropdownMenu>

      {/* Assign */}
      <DropdownMenu>
        <DropdownMenuTrigger
          render={
            <Button variant="ghost" size="sm" className="h-8 gap-1.5 text-xs">
              <User className="size-3.5" />
              Assign
            </Button>
          }
        />
        <DropdownMenuContent align="center" sideOffset={8}>
          <DropdownMenuLabel>Assign to</DropdownMenuLabel>
          <DropdownMenuSeparator />
          {assignees.map((assignee) => (
            <DropdownMenuItem
              key={assignee.id}
              onClick={() => bulkAssign(assignee.id)}
            >
              {assignee.name}
            </DropdownMenuItem>
          ))}
        </DropdownMenuContent>
      </DropdownMenu>

      {/* Snooze */}
      <Button
        variant="ghost"
        size="sm"
        className="h-8 gap-1.5 text-xs"
        onClick={bulkSnooze}
      >
        <Moon className="size-3.5" />
        Snooze
      </Button>

      {/* Archive */}
      <Button
        variant="ghost"
        size="sm"
        className="h-8 gap-1.5 text-xs"
        onClick={bulkArchive}
      >
        <Archive className="size-3.5" />
        Archive
      </Button>

      <div className="mx-1 h-5 w-px bg-border/70" />

      <Button
        variant="ghost"
        size="icon"
        className="size-8"
        aria-label="Clear selection"
        onClick={() => dispatch({ type: "CLEAR_SELECTION" })}
      >
        <X className="size-4" />
      </Button>
    </div>
  );
}

