"use client";

import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { useInboxState } from "./inbox-provider";

interface ShortcutItem {
  keys: readonly string[];
  label: string;
}

const GROUPS: ReadonlyArray<{ title: string; items: readonly ShortcutItem[] }> = [
  {
    title: "Navigation",
    items: [
      { keys: ["j", "↓"], label: "Next request" },
      { keys: ["k", "↑"], label: "Previous request" },
      { keys: ["Enter"], label: "Open selected" },
      { keys: ["Esc"], label: "Close / clear selection" },
    ],
  },
  {
    title: "Triage",
    items: [
      { keys: ["e"], label: "Archive" },
      { keys: ["s"], label: "Snooze" },
      { keys: ["a"], label: "Assign" },
      { keys: ["1"], label: "Set status → Backlog" },
      { keys: ["2"], label: "Set status → In Progress" },
      { keys: ["3"], label: "Set status → Review" },
      { keys: ["4"], label: "Set status → Delivered" },
    ],
  },
  {
    title: "Overlays",
    items: [
      { keys: ["⌘", "K"], label: "Open command palette" },
      { keys: ["?"], label: "Show this help" },
    ],
  },
];

function Kbd({ children }: { children: React.ReactNode }) {
  return (
    <kbd className="inline-flex min-w-[22px] items-center justify-center rounded-md border border-border/70 bg-muted px-1.5 py-0.5 text-[10px] font-medium text-foreground shadow-[var(--shadow-xs)]">
      {children}
    </kbd>
  );
}

export function ShortcutHelpDialog() {
  const { state, dispatch } = useInboxState();

  return (
    <Dialog
      open={state.helpOpen}
      onOpenChange={(open) => dispatch({ type: "SET_HELP_OPEN", open })}
    >
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle>Keyboard shortcuts</DialogTitle>
          <DialogDescription>
            Everything you need to triage an inbox without touching the mouse.
          </DialogDescription>
        </DialogHeader>
        <div className="grid gap-6 sm:grid-cols-3 pt-2">
          {GROUPS.map((group) => (
            <div key={group.title} className="space-y-2">
              <p className="text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">
                {group.title}
              </p>
              <ul className="space-y-1.5">
                {group.items.map((item) => (
                  <li
                    key={item.label}
                    className="flex items-center justify-between gap-3 text-xs"
                  >
                    <span className="text-foreground/90">{item.label}</span>
                    <span className="flex items-center gap-1">
                      {item.keys.map((key) => (
                        <Kbd key={key}>{key}</Kbd>
                      ))}
                    </span>
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>
      </DialogContent>
    </Dialog>
  );
}

