          <DropdownMenuItem key={assignee.id} onClick={() => onPick(assignee.id)}>
            {assignee.name}
            <span className="ml-auto text-[10px] text-muted-foreground">
              {assignee.role}
            </span>
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function DetailTimeline({ request }: { request: Request }) {
  const { state, assigneeById } = useInboxState();
  const events = state.timeline[request.id] ?? [];
  const comments = state.comments[request.id] ?? [];

  const merged = [
    ...events.map((e) => ({ kind: "event" as const, id: e.id, at: e.timestamp, payload: e })),
    ...comments.map((c) => ({ kind: "comment" as const, id: c.id, at: c.createdAt, payload: c })),
  ].sort((a, b) => new Date(a.at).getTime() - new Date(b.at).getTime());

  if (merged.length === 0) {
    return (
      <div className="rounded-lg border border-dashed border-border/60 bg-muted/30 px-4 py-6 text-center text-xs text-muted-foreground">
        No activity yet.
      </div>
    );
  }

  return (
    <ol className="relative space-y-4 border-l border-border/60 pl-5">
      {merged.map((entry) => {
        if (entry.kind === "comment") {
          const author = assigneeById(entry.payload.authorId);
          return (
            <li key={entry.id} className="relative">
              <span className="absolute -left-[25px] top-1 flex size-2.5 items-center justify-center">
                <span className="size-2 rounded-full bg-primary ring-4 ring-background" />
              </span>
              <div className="flex items-start gap-2.5">
                {author ? (
                  <Avatar className="size-6">
                    <AvatarImage src={author.avatarUrl} alt={author.name} />
                    <AvatarFallback className="text-[9px]">
                      {initials(author.name)}
                    </AvatarFallback>
                  </Avatar>
                ) : null}
                <div className="flex-1 rounded-lg border border-border/60 bg-card px-3 py-2 shadow-[var(--shadow-xs)]">
                  <div className="flex items-center gap-2">
                    <span className="text-xs font-medium">
                      {author?.name ?? "Unknown"}
                    </span>
                    <span className="text-[10px] text-muted-foreground">
                      {formatRelative(entry.at)}
                    </span>
                  </div>
                  <p className="mt-1 text-xs text-foreground/90">{entry.payload.body}</p>
                </div>
              </div>
            </li>
          );
        }

        const actor = assigneeById(entry.payload.actorId);
        const label = eventLabel(entry.payload.type, entry.payload.meta);
        return (
          <li key={entry.id} className="relative flex items-center gap-2 text-xs text-muted-foreground">
            <span className="absolute -left-[23px] top-1/2 -translate-y-1/2 size-1.5 rounded-full bg-muted-foreground/60 ring-4 ring-background" />
            <span className="font-medium text-foreground/80">
              {actor?.name ?? "System"}
            </span>
            <span>{label}</span>
            <span className="ml-auto tabular-nums text-[10px]">
              {formatRelative(entry.at)}
            </span>
          </li>
        );
      })}
    </ol>
  );
}

function eventLabel(
  type: import("@/lib/types").TimelineEventType,
  meta?: Readonly<Record<string, string>>,
): string {
  switch (type) {
    case "request_created":
      return "created this request";
    case "status_changed":
      return `moved ${meta?.from ?? ""} → ${meta?.to ?? ""}`;
    case "priority_changed":
      return `changed priority ${meta?.from ?? ""} → ${meta?.to ?? ""}`;
    case "assignee_changed":
      return "reassigned";
    case "snoozed":
      return "snoozed";
    case "unsnoozed":
      return "unsnoozed";
    case "archived":
      return "archived";
    case "unarchived":
      return "restored";
    case "comment_added":
      return "commented";
    case "tag_added":
      return `added tag ${meta?.tag ?? ""}`;
    case "tag_removed":
      return `removed tag ${meta?.tag ?? ""}`;
  }
}

function ReplyComposer({ request }: { request: Request }) {
  const { dispatch, currentUser } = useInboxState();
  const [body, setBody] = useState("");

  function send() {
    const trimmed = body.trim();
    if (trimmed.length === 0) return;
    dispatch({
      type: "ADD_COMMENT",
      requestId: request.id,
      body: trimmed,
      authorId: currentUser.id,
    });
    toast.success("Reply sent");
    setBody("");
  }

  return (
    <div className="border-t border-border/60 bg-background/80 backdrop-blur-sm p-4">
      <div className="rounded-xl border border-border/60 bg-card shadow-[var(--shadow-soft)] focus-within:ring-2 focus-within:ring-primary/20 focus-within:border-primary/40 transition-all">
        <Textarea
          value={body}
          onChange={(event) => setBody(event.target.value)}
          onKeyDown={(event) => {
            if ((event.metaKey || event.ctrlKey) && event.key === "Enter") {
              event.preventDefault();
              send();
            }
          }}
          placeholder="Write a reply… (⌘⏎ to send)"
          rows={3}
          className="border-0 shadow-none resize-none focus-visible:ring-0 focus-visible:ring-offset-0 bg-transparent text-sm"
        />
        <div className="flex items-center justify-between border-t border-border/60 px-3 py-2">
          <p className="text-[11px] text-muted-foreground">Mock — demo only</p>
          <Button size="sm" onClick={send} disabled={body.trim().length === 0}>
            <CornerDownRight className="size-3.5" />
            Send reply
          </Button>
        </div>
      </div>
    </div>
  );
}

function LoadedDetail({ request, client, assignee, assignees }: LoadedDetailProps) {
  const { dispatch } = useInboxState();

  function handleArchive() {
    dispatch({ type: "TOGGLE_ARCHIVE", id: request.id });
    toast.success(request.isArchived ? "Restored" : "Archived");
  }

  return (
    <div className="flex h-full flex-col">
      {/* Header — glass */}
      <div className="sticky top-0 z-10 border-b border-border/60 bg-background/85 backdrop-blur-md">
        <div className="flex items-start gap-3 px-5 py-4">
          <div className="flex-1 min-w-0 space-y-2">
            <div className="flex items-center gap-2 text-[11px] text-muted-foreground">
              {client ? (
                <span className="inline-flex items-center gap-1.5">
                  <Avatar className="size-4">
                    <AvatarImage src={client.avatarUrl} alt={client.company} />
                    <AvatarFallback className="text-[8px]">
                      {initials(client.company)}
                    </AvatarFallback>
                  </Avatar>
                  <span className="font-medium text-foreground/80">
                    {client.company}
                  </span>
                </span>
              ) : null}
              <span>·</span>
              <span>Created {formatRelative(request.createdAt)}</span>
            </div>
            <h2 className="text-lg font-semibold tracking-tight leading-tight">
              {request.title}
            </h2>
            <div className="flex flex-wrap items-center gap-2">
              <StatusEditor request={request} />
              <PriorityEditor request={request} />
              <SlaChip slaDueAt={request.slaDueAt} />
              <AssigneeEditor request={request} assignees={assignees} />
            </div>
          </div>
          <div className="flex items-center gap-1">
            <SnoozeMenu
              requestId={request.id}
              align="end"
              trigger={
                <Button
                  variant="ghost"
                  size="icon"
                  aria-label="Snooze"
                  className="size-8"
                >
                  <Moon className="size-4" />
                </Button>
              }
            />
            <Button
              variant="ghost"
              size="icon"
              aria-label={request.isArchived ? "Unarchive" : "Archive"}
              className="size-8"
              onClick={handleArchive}
            >
              <Archive className="size-4" />
            </Button>
            <Button
              variant="ghost"
              size="icon"
              aria-label="Close"
              className="size-8"
              onClick={() => dispatch({ type: "SELECT_REQUEST", id: null })}
            >
              <X className="size-4" />
            </Button>
          </div>
        </div>
      </div>

      {/* Body */}
      <ScrollArea className="flex-1">
        <div className="space-y-6 px-5 py-5">
          {/* Metadata grid */}
          <div className="grid grid-cols-2 gap-3 rounded-xl border border-border/60 bg-card p-4 shadow-[var(--shadow-xs)]">
            <MetaRow icon={<CheckCircle2 className="size-3.5" />} label="Status" value={STATUS_LABELS[request.status]} />
            <MetaRow icon={<Flag className="size-3.5" />} label="Priority" value={PRIORITY_LABELS[request.priority]} />
            <MetaRow icon={<User className="size-3.5" />} label="Assignee" value={assignee?.name ?? "Unassigned"} />
            <MetaRow icon={<MessageCircle className="size-3.5" />} label="Last activity" value={formatRelative(request.lastActivityAt ?? request.createdAt)} />
          </div>

          {/* Original message */}
          <section className="space-y-2">
            <p className="text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">
              Original message
            </p>
            <div className="rounded-xl border border-border/60 bg-muted/30 px-4 py-3 text-sm leading-relaxed text-foreground/90">
              {request.rawMessage}
            </div>
          </section>

          {/* Tags */}
          {request.tags.length > 0 ? (
            <section className="space-y-2">
              <p className="text-[11px] font-semibold uppercase tracking-wide text-muted-foreground flex items-center gap-1.5">
                <Tag className="size-3" /> Tags
              </p>
              <div className="flex flex-wrap gap-1.5">
                {request.tags.map((tag) => (
                  <span
                    key={tag}
                    className="rounded-md bg-muted px-2 py-0.5 text-[11px] font-medium text-muted-foreground ring-1 ring-border/60"
                  >
                    {tag}
                  </span>
                ))}
              </div>
            </section>
          ) : null}

          {/* Activity */}
          <section className="space-y-3">
            <p className="text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">
              Activity
            </p>
            <DetailTimeline request={request} />
          </section>
        </div>
      </ScrollArea>

      <ReplyComposer request={request} />
    </div>
  );
}

function MetaRow({
  icon,
  label,
  value,
}: {
  icon: React.ReactNode;
  label: string;
  value: string;
}) {
  return (
    <div className="flex items-center gap-2 text-xs">
      <span className="text-muted-foreground">{icon}</span>
      <span className="text-muted-foreground">{label}</span>
      <span className={cn("ml-auto font-medium text-foreground/90 truncate")}>
        {value}
      </span>
    </div>
  );
}

export function DetailPanel() {
  const { selectedRequest, clientById, assigneeById, assignees } = useInboxState();

  if (!selectedRequest) {
    return (
      <section className="hidden md:flex h-full flex-col bg-background">
        <DetailEmptyState />
      </section>
    );
  }

  const client = clientById(selectedRequest.clientId);
  const assignee = assigneeById(selectedRequest.assigneeId);

  return (
    <section
      aria-label="Request detail"
      className="hidden md:flex h-full flex-col bg-background border-l border-border/60"
    >
      <LoadedDetail
        request={selectedRequest}
        client={client}
        assignee={assignee}
        assignees={assignees}
      />
    </section>
  );
}

