  const client = clientById(request.clientId);
  const assignee = assigneeById(request.assigneeId);
  const commentCount = (state.comments[request.id] ?? []).length;

  const unread = !(request.isRead ?? false);
  const snoozed = !!request.snoozeUntil;

  function handleClick() {
    dispatch({ type: "SELECT_REQUEST", id: request.id });
    onFocus(index);
  }

  function handleArchive(event: React.MouseEvent) {
    event.stopPropagation();
    dispatch({ type: "TOGGLE_ARCHIVE", id: request.id });
  }

  function handleSnooze(event: React.MouseEvent) {
    event.stopPropagation();
    dispatch({ type: "SET_SNOOZE_TARGET", id: request.id });
  }

  return (
    <div
      role="button"
      tabIndex={0}
      data-priority={request.priority}
      data-selected={isSelected}
      data-focused={isFocused}
      data-unread={unread}
      onClick={handleClick}
      onKeyDown={(event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          handleClick();
        }
      }}
      className={cn(
        "group relative flex items-stretch gap-3 border-b border-border/60 pl-4 pr-3 py-3 cursor-pointer",
        "transition-colors duration-[var(--duration-fast)]",
        "hover:bg-muted/50",
        "data-[selected=true]:bg-primary/[0.06] data-[selected=true]:ring-1 data-[selected=true]:ring-primary/20",
        "data-[focused=true]:outline-none data-[focused=true]:ring-2 data-[focused=true]:ring-ring",
      )}
    >
      {/* Priority stripe */}
      <span
        aria-hidden="true"
        className={cn(
          "absolute inset-y-0 left-0 w-[3px]",
          request.priority === "urgent" && "bg-destructive",
          request.priority === "high" && "bg-amber-500",
          request.priority === "normal" && "bg-primary/40",
          request.priority === "low" && "bg-muted-foreground/30",
        )}
      />

      {/* Bulk checkbox */}
      <div
        onClick={(event) => event.stopPropagation()}
        className="flex items-center pl-1"
      >
        <Checkbox
          checked={isBulkSelected}
          onCheckedChange={() =>
            dispatch({ type: "TOGGLE_ROW_SELECTED", id: request.id })
          }
          aria-label={`Select ${request.title}`}
          className="size-4"
        />
      </div>

      {/* Unread dot */}
      <div className="flex items-center pt-[7px]">
        {unread ? (
          <span
            aria-label="Unread"
            className="size-2 rounded-full bg-primary shadow-[0_0_0_3px_color-mix(in_oklch,var(--primary)_15%,transparent)]"
          />
        ) : (
          <span className="size-2" aria-hidden="true" />
        )}
      </div>

      {/* Content */}
      <div className="flex-1 min-w-0 flex flex-col gap-1">
        {/* Row 1 — title + SLA */}
        <div className="flex items-center gap-2">
          <h3
            className={cn(
              "truncate text-sm leading-5",
              unread ? "font-semibold text-foreground" : "font-medium text-foreground/90",
            )}
          >
            {request.title}
          </h3>
          <div className="ml-auto flex items-center gap-1.5 shrink-0">
            <SlaChip slaDueAt={request.slaDueAt} />
          </div>
        </div>

        {/* Row 2 — message preview */}
        <p className="truncate text-xs text-muted-foreground">
          {client?.company ? (
            <>
              <span className="text-foreground/70 font-medium">{client.company}</span>
              <span className="mx-1.5 text-muted-foreground/60">·</span>
            </>
          ) : null}
          {request.rawMessage}
        </p>

        {/* Row 3 — meta: tags, comments, assignee, time */}
        <div className="flex items-center gap-2 text-[11px] text-muted-foreground">
          {request.tags.slice(0, 2).map((tag) => (
            <span
              key={tag}
              className="rounded-md bg-muted px-1.5 py-0.5 text-[10px] font-medium text-muted-foreground ring-1 ring-border/60"
            >
              {tag}
            </span>
          ))}

          {commentCount > 0 ? (
            <span className="inline-flex items-center gap-1">
              <MessageSquare className="size-3" />
              {commentCount}
            </span>
          ) : null}

          {snoozed ? (
            <span className="inline-flex items-center gap-1 text-primary/80">
              <Moon className="size-3" />
              Snoozed
            </span>
          ) : null}

          <span className="ml-auto tabular-nums">{formatRelative(request.lastActivityAt ?? request.createdAt)}</span>

          {assignee ? (
            <Avatar className="size-5 ring-1 ring-border">
              <AvatarImage src={assignee.avatarUrl} alt={assignee.name} />
              <AvatarFallback className="text-[9px]">
                {initials(assignee.name)}
              </AvatarFallback>
            </Avatar>
          ) : null}
        </div>
      </div>

      {/* Hover actions */}
      <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity duration-[var(--duration-fast)] bg-background/90 backdrop-blur-sm rounded-md px-1 py-0.5 shadow-[var(--shadow-xs)]">
        <button
          type="button"
          onClick={handleSnooze}
          aria-label="Snooze"
          className="inline-flex size-6 items-center justify-center rounded-md text-muted-foreground hover:bg-muted hover:text-foreground transition-colors"
        >
          <Moon className="size-3.5" />
        </button>
        <button
          type="button"
          onClick={handleArchive}
          aria-label={request.isArchived ? "Unarchive" : "Archive"}
          className="inline-flex size-6 items-center justify-center rounded-md text-muted-foreground hover:bg-muted hover:text-foreground transition-colors"
        >
          <Archive className="size-3.5" />
        </button>
      </div>
    </div>
  );
}

