"use client";

import { useEffect, useState } from "react";
import { toast } from "sonner";
import {
  Command as CommandIcon,
  Inbox as InboxIcon,
  Mail,
  User,
  TriangleAlert,
  Flame,
  Moon,
  Archive as ArchiveIcon,
  CircleDot,
  Flag,
} from "lucide-react";
import {
  Command,
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
} from "cmdk";
import type { Priority, RequestStatus, SegmentIconName, SegmentId } from "@/lib/types";
import { useInboxState } from "./inbox-provider";
import {
  PRIORITY_LABELS,
  PRIORITY_ORDER,
  STATUS_LABELS,
  STATUS_ORDER,
} from "@/lib/inbox/labels";
import { resolveSnoozeTime, SNOOZE_PRESETS } from "@/lib/inbox/snooze";

const SEGMENT_ICONS: Record<SegmentIconName, typeof InboxIcon> = {
  inbox: InboxIcon,
  mail: Mail,
  user: User,
  "alert-triangle": TriangleAlert,
  flame: Flame,
  moon: Moon,
  archive: ArchiveIcon,
};

export function CommandPalette() {
  const {
    state,
    dispatch,
    segments,
    assignees,
    visibleRequests,
    selectedRequest,
  } = useInboxState();
  const [search, setSearch] = useState("");

  // Clear search when closing
  useEffect(() => {
    if (!state.paletteOpen) setSearch("");
  }, [state.paletteOpen]);

  function close() {
    dispatch({ type: "SET_PALETTE_OPEN", open: false });
  }

