"use client";

import { useMemo, useState } from "react";
import { toast } from "sonner";
import {
  DndContext,
  DragOverlay,
  KeyboardSensor,
  PointerSensor,
  closestCorners,
  useSensor,
  useSensors,
  type DragEndEvent,
  type DragStartEvent,
} from "@dnd-kit/core";
import {
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
  useSortable,
} from "@dnd-kit/sortable";
import { useDroppable } from "@dnd-kit/core";
import type { Request, RequestStatus } from "@/lib/types";
import { STATUS_LABELS, STATUS_ORDER } from "@/lib/inbox/labels";
import { ScrollArea } from "@/components/ui/scroll-area";
import { cn } from "@/lib/utils";
import { useInboxState } from "./inbox-provider";
import { KanbanCard } from "./kanban-card";

function KanbanColumn({
  status,
  requests,
  onCardClick,
}: {
  status: RequestStatus;
  requests: readonly Request[];
  onCardClick: (id: string) => void;
}) {
  const { clientById, assigneeById } = useInboxState();
  const { setNodeRef, isOver } = useDroppable({ id: status, data: { status } });

  return (
    <div className="flex min-w-[260px] flex-1 flex-col">
      <div className="flex items-center justify-between px-3 py-2">
        <div className="flex items-center gap-2">
          <span
            aria-hidden="true"
            className={cn(
              "size-1.5 rounded-full",
              status === "backlog" && "bg-sky-500",
              status === "in_progress" && "bg-slate-500",
              status === "review" && "bg-amber-500",
              status === "delivered" && "bg-emerald-500",
            )}
          />
          <span className="text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">
            {STATUS_LABELS[status]}
          </span>
          <span className="rounded-full bg-muted px-1.5 py-0.5 text-[10px] font-medium tabular-nums text-muted-foreground">
            {requests.length}
          </span>
        </div>
      </div>
      <div
        ref={setNodeRef}
        data-over={isOver}
        className={cn(
          "flex flex-1 flex-col gap-2.5 rounded-xl border border-dashed border-transparent p-2 transition-colors",
          "data-[over=true]:border-primary/40 data-[over=true]:bg-primary/5",
        )}
      >
        <SortableContext
          items={requests.map((r) => r.id)}
          strategy={verticalListSortingStrategy}
        >
          {requests.map((req) => (
            <KanbanCard
              key={req.id}
              request={req}
              client={clientById(req.clientId)}
              assignee={assigneeById(req.assigneeId)}
              onClick={() => onCardClick(req.id)}
            />
          ))}
        </SortableContext>
        {requests.length === 0 ? (
          <div className="flex flex-1 items-center justify-center rounded-lg border border-dashed border-border/50 py-8 text-[11px] text-muted-foreground">
            Drop requests here
          </div>
        ) : null}
      </div>
    </div>
  );
}

function DragPreview({ request }: { request: Request }) {
  const { clientById, assigneeById } = useInboxState();
  // Use non-sortable wrapper for the overlay — reuse the visual card but detach from sortable.
  return (
    <div className="w-[280px]">
      <KanbanCard
        request={request}
        client={clientById(request.clientId)}
        assignee={assigneeById(request.assigneeId)}
        dragging
      />
    </div>
  );
}

void useSortable; // retained for potential overlay expansion

export function KanbanBoard() {
  const { state, dispatch, visibleRequests } = useInboxState();
  const [activeId, setActiveId] = useState<string | null>(null);

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 4 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates }),
  );

  const columns = useMemo(() => {
    const grouped: Record<RequestStatus, Request[]> = {
      backlog: [],
      in_progress: [],
      review: [],
      delivered: [],
    };
    for (const req of visibleRequests) {
      grouped[req.status].push(req);
    }
    return grouped;
  }, [visibleRequests]);

  function handleDragStart(event: DragStartEvent) {
    setActiveId(String(event.active.id));
  }

  function handleDragEnd(event: DragEndEvent) {
    setActiveId(null);
    const { active, over } = event;
    if (!over) return;
    const activeRequest = state.requests.find((r) => r.id === active.id);
    if (!activeRequest) return;

    // Determine destination column: if over id equals a status, use it;
    // otherwise find the request under the cursor and use its status.
    let nextStatus: RequestStatus | null = null;
    const overId = String(over.id);
    if (STATUS_ORDER.includes(overId as RequestStatus)) {
      nextStatus = overId as RequestStatus;
    } else {
      const overRequest = state.requests.find((r) => r.id === overId);
      nextStatus = overRequest?.status ?? null;
    }
    if (!nextStatus || nextStatus === activeRequest.status) return;

    const previousStatus = activeRequest.status;
    dispatch({ type: "SET_STATUS", id: activeRequest.id, status: nextStatus });
    toast.success(`Moved to ${STATUS_LABELS[nextStatus]}`, {
      action: {
        label: "Undo",
        onClick: () => {
          dispatch({
            type: "SET_STATUS",
            id: activeRequest.id,
            status: previousStatus,
          });
        },
      },
    });
  }

  const activeRequest = activeId
    ? state.requests.find((r) => r.id === activeId) ?? null
    : null;

  return (
    <ScrollArea className="h-full">
      <div className="h-full px-4 py-4">
        <DndContext
          sensors={sensors}
          collisionDetection={closestCorners}
          onDragStart={handleDragStart}
          onDragEnd={handleDragEnd}
        >
          <div className="flex h-full gap-4 min-w-[1100px]">
            {STATUS_ORDER.map((status) => (
              <KanbanColumn
                key={status}
                status={status}
                requests={columns[status]}
                onCardClick={(id) => dispatch({ type: "SELECT_REQUEST", id })}
              />
            ))}
          </div>
          <DragOverlay>
            {activeRequest ? <DragPreview request={activeRequest} /> : null}
          </DragOverlay>
        </DndContext>
      </div>
    </ScrollArea>
  );
}

