        label: "Undo",
        onClick: () => {
          dispatch({
            type: "SET_STATUS",
            id: activeRequest.id,
            status: previousStatus,
          });
        },
      },
    });
  }

  const activeRequest = activeId
    ? state.requests.find((r) => r.id === activeId) ?? null
    : null;

  return (
    <ScrollArea className="h-full">
      <div className="h-full px-4 py-4">
        <DndContext
          sensors={sensors}
          collisionDetection={closestCorners}
          onDragStart={handleDragStart}
          onDragEnd={handleDragEnd}
        >
          <div className="flex h-full gap-4 min-w-[1100px]">
            {STATUS_ORDER.map((status) => (
              <KanbanColumn
                key={status}
                status={status}
                requests={columns[status]}
                onCardClick={(id) => dispatch({ type: "SELECT_REQUEST", id })}
              />
            ))}
          </div>
          <DragOverlay>
            {activeRequest ? <DragPreview request={activeRequest} /> : null}
          </DragOverlay>
        </DndContext>
      </div>
    </ScrollArea>
  );
}

