"use client";

import { useCallback, useEffect, useState } from "react";
import { toast } from "sonner";
import { Sheet, SheetContent } from "@/components/ui/sheet";
import { useInboxHotkeys } from "@/hooks/use-inbox-hotkeys";
import { useMediaQuery } from "@/hooks/use-media-query";
import { resolveSnoozeTime } from "@/lib/inbox/snooze";
import { statusFromSlot } from "@/lib/inbox/labels";
import { cn } from "@/lib/utils";
import { BulkActionBar } from "./bulk-action-bar";
import { CommandPalette } from "./command-palette";
import { DetailPanel } from "./detail-panel";
import { InboxTopbar } from "./inbox-topbar";
import { KanbanBoard } from "./kanban-board";
import { RequestList } from "./request-list";
import { SegmentRail } from "./segment-rail";
import { ShortcutHelpDialog } from "./shortcut-help-dialog";
import { useInboxState } from "./inbox-provider";

export function InboxWorkspace() {
  const { state, dispatch, visibleRequests, selectedRequest } = useInboxState();
  const [focusedIndex, setFocusedIndex] = useState<number>(-1);
  const isDesktop = useMediaQuery("(min-width: 768px)");

  // Keep focus valid when visible list changes.
  useEffect(() => {
    if (visibleRequests.length === 0) {
      setFocusedIndex(-1);
      return;
    }
    setFocusedIndex((prev) => {
      if (prev < 0) return 0;
      if (prev >= visibleRequests.length) return visibleRequests.length - 1;
      return prev;
    });
  }, [visibleRequests]);

  const navigate = useCallback(
    (delta: number) => {
      if (visibleRequests.length === 0) return;
      setFocusedIndex((prev) => {
        const base = prev < 0 ? 0 : prev;
        const next = Math.min(
          Math.max(base + delta, 0),
          visibleRequests.length - 1,
        );
        return next;
      });
    },
    [visibleRequests.length],
  );

  const focusedRequest =
    focusedIndex >= 0 && focusedIndex < visibleRequests.length
      ? visibleRequests[focusedIndex]
      : null;
  const targetRequest = selectedRequest ?? focusedRequest;

  useInboxHotkeys({
    disabled: false,
    paletteOpen: state.paletteOpen || state.helpOpen,
    onNavigateDown: () => navigate(1),
    onNavigateUp: () => navigate(-1),
    onOpen: () => {
      if (focusedRequest) {
        dispatch({ type: "SELECT_REQUEST", id: focusedRequest.id });
      }
    },
    onArchive: () => {
      if (!targetRequest) return;
      dispatch({ type: "TOGGLE_ARCHIVE", id: targetRequest.id });
      toast.success(targetRequest.isArchived ? "Restored" : "Archived");
    },
    onSnooze: () => {
      if (!targetRequest) return;
      const until = resolveSnoozeTime("tomorrow");
      dispatch({ type: "SNOOZE", id: targetRequest.id, until });
      toast.success("Snoozed until tomorrow");
    },
    onAssign: () => {
      dispatch({ type: "SET_PALETTE_OPEN", open: true });
    },
    onSetStatus: (slot) => {
      if (!targetRequest) return;
      dispatch({
        type: "SET_STATUS",
        id: targetRequest.id,
        status: statusFromSlot(slot),
      });
    },
    onOpenPalette: () => dispatch({ type: "SET_PALETTE_OPEN", open: true }),
    onShowHelp: () => dispatch({ type: "SET_HELP_OPEN", open: true }),
    onEscape: () => {
      if (state.paletteOpen) {
        dispatch({ type: "SET_PALETTE_OPEN", open: false });
        return;
      }
      if (state.helpOpen) {
        dispatch({ type: "SET_HELP_OPEN", open: false });
        return;
      }
      if (state.bulkSelection.size > 0) {
        dispatch({ type: "CLEAR_SELECTION" });
        return;
      }
      if (state.selectedRequestId) {
        dispatch({ type: "SELECT_REQUEST", id: null });
      }
    },
  });

  const isKanban = state.view === "kanban";

  return (
    <div className="flex h-[calc(100svh-4rem)] flex-col bg-background">
      <InboxTopbar />

      <div
        className={cn(
          "grid flex-1 min-h-0",
          isKanban
            ? "grid-cols-1 md:grid-cols-[56px_1fr] xl:grid-cols-[240px_1fr]"
            : "grid-cols-1 md:grid-cols-[56px_minmax(360px,420px)_1fr] xl:grid-cols-[240px_minmax(380px,440px)_1fr]",
        )}
      >
        <SegmentRail />

        {isKanban ? (
          <div className="min-w-0 min-h-0 overflow-hidden">
            <KanbanBoard />
          </div>
        ) : (
          <>
            <div className="min-w-0 min-h-0 border-r border-border/60 overflow-hidden">
              <RequestList
                focusedIndex={focusedIndex}
                onFocusIndex={setFocusedIndex}
              />
            </div>
            <div className="min-w-0 min-h-0 overflow-hidden">
              <DetailPanel />
            </div>
          </>
        )}
      </div>

      <BulkActionBar />
      <CommandPalette />
      <ShortcutHelpDialog />

      {/* Mobile / kanban detail: Sheet */}
      {(isKanban || !isDesktop) && selectedRequest ? (
        <Sheet
          open={true}
          onOpenChange={(open) => {
            if (!open) dispatch({ type: "SELECT_REQUEST", id: null });
          }}
        >
          <SheetContent
            side="right"
            className="w-full sm:max-w-lg p-0 flex flex-col"
            showCloseButton={false}
          >
            <div className="flex h-full flex-col">
              <DetailPanel />
            </div>
          </SheetContent>
        </Sheet>
      ) : null}
    </div>
  );
}

