"use client";

import { toast } from "sonner";
import { Moon, BellOff } from "lucide-react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { SNOOZE_PRESETS, resolveSnoozeTime } from "@/lib/inbox/snooze";
import { useInboxState } from "./inbox-provider";

interface SnoozeMenuProps {
  requestId: string;
  trigger: React.ReactNode;
  align?: "start" | "center" | "end";
}

export function SnoozeMenu({ requestId, trigger, align = "end" }: SnoozeMenuProps) {
  const { state, dispatch } = useInboxState();
  const target = state.requests.find((r) => r.id === requestId);
  const isSnoozed = !!target?.snoozeUntil;

  function applyPreset(presetId: (typeof SNOOZE_PRESETS)[number]["id"]) {
    const until = resolveSnoozeTime(presetId);
    const label = SNOOZE_PRESETS.find((p) => p.id === presetId)?.label ?? "later";
    dispatch({ type: "SNOOZE", id: requestId, until });
    toast.success(`Snoozed until ${label.toLowerCase()}`);
  }

  function unsnooze() {
    dispatch({ type: "SNOOZE", id: requestId, until: null });
    toast.success("Unsnoozed");
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger render={trigger} />
      <DropdownMenuContent align={align} sideOffset={8} className="w-52">
        <DropdownMenuLabel className="flex items-center gap-1.5">
          <Moon className="size-3.5" /> Snooze until
        </DropdownMenuLabel>
        <DropdownMenuSeparator />
        {SNOOZE_PRESETS.map((preset) => (
          <DropdownMenuItem
            key={preset.id}
            onClick={() => applyPreset(preset.id)}
            className="flex items-center justify-between"
          >
            <span>{preset.label}</span>
            <span className="text-[10px] text-muted-foreground">{preset.hint}</span>
          </DropdownMenuItem>
        ))}
        {isSnoozed ? (
          <>
            <DropdownMenuSeparator />
            <DropdownMenuItem onClick={unsnooze}>
              <BellOff className="size-3.5" /> Unsnooze now
            </DropdownMenuItem>
          </>
        ) : null}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

