"use client";

import { useMemo, useState } from "react";
import Link from "next/link";
import { toast } from "sonner";
import {
  AlertTriangle,
  AtSign,
  Bell,
  Check,
  CheckCheck,
  Inbox as InboxIcon,
  MessageSquare,
  Settings,
  Sparkles,
  UserPlus,
} from "lucide-react";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { ScrollArea } from "@/components/ui/scroll-area";
import { notifications as seedNotifications } from "@/lib/mock/notifications";
import type { AppNotification, NotificationType } from "@/lib/mock/notifications";
import { formatRelative } from "@/lib/utils/time";
import { cn } from "@/lib/utils";

const ICONS: Record<NotificationType, React.ComponentType<{ className?: string }>> = {
  request_new: InboxIcon,
  sla_breached: AlertTriangle,
  mention: AtSign,
  comment: MessageSquare,
  status_changed: Sparkles,
  assigned: UserPlus,
};

const TONES: Record<NotificationType, string> = {
  request_new: "bg-primary/10 text-primary",
  sla_breached: "bg-rose-50 text-rose-600 ring-1 ring-rose-200",
  mention: "bg-amber-50 text-amber-600 ring-1 ring-amber-200",
  comment: "bg-sky-50 text-sky-600 ring-1 ring-sky-200",
  status_changed: "bg-emerald-50 text-emerald-600 ring-1 ring-emerald-200",
  assigned: "bg-primary/10 text-primary",
};

type FilterKey = "all" | "unread";

function initials(name: string): string {
  return name
    .split(" ")
    .map((part) => part[0])
    .filter(Boolean)
    .slice(0, 2)
    .join("")
    .toUpperCase();
}

export function NotificationsMenu() {
  const [items, setItems] = useState<readonly AppNotification[]>(seedNotifications);
  const [filter, setFilter] = useState<FilterKey>("all");

  const unreadCount = useMemo(
    () => items.filter((item) => !item.isRead).length,
    [items],
  );

  const visible = useMemo(() => {
    if (filter === "unread") return items.filter((item) => !item.isRead);
    return items;
  }, [items, filter]);

  function markAllRead() {
    setItems((prev) => prev.map((item) => ({ ...item, isRead: true })));
    toast.success("All notifications marked as read");
  }

  function markOneRead(id: string) {
    setItems((prev) =>
      prev.map((item) => (item.id === id ? { ...item, isRead: true } : item)),
    );
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <button
            type="button"
            aria-label="Notifications"
            className="relative inline-flex size-8 items-center justify-center rounded-md text-foreground/80 hover:bg-muted hover:text-foreground transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          />
        }
      >
        <Bell className="size-4" />
        {unreadCount > 0 ? (
          <>
            <span className="absolute top-1.5 right-1.5 size-2 rounded-full bg-destructive ring-2 ring-background animate-pulse" />
            <span className="sr-only">{unreadCount} unread notifications</span>
          </>
        ) : null}
      </DropdownMenuTrigger>

      <DropdownMenuContent
        align="end"
        sideOffset={8}
        className="w-[380px] p-0 overflow-hidden"
      >
        {/* Header */}
        <div className="flex items-center justify-between border-b border-border/60 px-4 py-3">
          <div className="flex items-center gap-2">
            <p className="text-sm font-semibold tracking-tight">Notifications</p>
            {unreadCount > 0 ? (
              <span className="rounded-full bg-primary/10 px-1.5 py-0.5 text-[10px] font-medium text-primary tabular-nums">
                {unreadCount} new
              </span>
            ) : null}
          </div>
          <button
            type="button"
            onClick={markAllRead}
            disabled={unreadCount === 0}
            className="inline-flex items-center gap-1 text-[11px] font-medium text-muted-foreground hover:text-foreground disabled:opacity-40 transition-colors"
          >
            <CheckCheck className="size-3" />
            Mark all read
          </button>
        </div>

        {/* Filter tabs */}
        <div className="flex gap-1 border-b border-border/60 bg-muted/30 px-2 py-1.5">
          <FilterPill
            active={filter === "all"}
            onClick={() => setFilter("all")}
            label="All"
            count={items.length}
          />
          <FilterPill
            active={filter === "unread"}
            onClick={() => setFilter("unread")}
            label="Unread"
            count={unreadCount}
          />
        </div>

        {/* List */}
        {visible.length === 0 ? (
          <div className="flex flex-col items-center justify-center gap-2 px-6 py-10 text-center">
            <div className="flex size-10 items-center justify-center rounded-full bg-muted text-muted-foreground">
              <Check className="size-4" />
            </div>
            <p className="text-xs font-medium">All caught up</p>
            <p className="text-[11px] text-muted-foreground">
              No {filter === "unread" ? "unread " : ""}notifications.
            </p>
          </div>
        ) : (
          <ScrollArea className="max-h-[380px]">
            <ul>
              {visible.map((item) => {
                const Icon = ICONS[item.type];
                return (
                  <li key={item.id}>
                    <Link
                      href={item.href}
                      onClick={() => markOneRead(item.id)}
                      className={cn(
                        "group relative flex items-start gap-3 px-4 py-3 border-b border-border/60 last:border-b-0 hover:bg-muted/50 transition-colors",
                      )}
                    >
                      {!item.isRead ? (
                        <span
                          aria-hidden="true"
                          className="absolute left-1.5 top-1/2 size-1.5 -translate-y-1/2 rounded-full bg-primary"
                        />
                      ) : null}
                      <div
                        className={cn(
                          "flex size-8 shrink-0 items-center justify-center rounded-lg",
                          TONES[item.type],
                        )}
                      >
                        {item.actorAvatarUrl && item.type !== "sla_breached" ? (
                          <Avatar className="size-8">
                            <AvatarImage src={item.actorAvatarUrl} alt={item.actorName} />
                            <AvatarFallback className="text-[10px]">
                              {initials(item.actorName)}
                            </AvatarFallback>
                          </Avatar>
                        ) : (
                          <Icon className="size-4" />
                        )}
                      </div>
                      <div className="min-w-0 flex-1 space-y-0.5">
                        <p
                          className={cn(
                            "text-[13px] leading-tight truncate",
                            item.isRead
                              ? "font-medium text-foreground/80"
                              : "font-semibold text-foreground",
                          )}
                        >
                          {item.title}
                        </p>
                        <p className="text-[11px] text-muted-foreground truncate">
                          {item.body}
                        </p>
                        <p className="text-[10px] text-muted-foreground/80 tabular-nums">
                          {formatRelative(item.createdAt)}
                        </p>
                      </div>
                    </Link>
                  </li>
                );
              })}
            </ul>
          </ScrollArea>
        )}

        {/* Footer */}
        <div className="flex items-center justify-between border-t border-border/60 bg-muted/20 px-3 py-2">
          <Button
            variant="ghost"
            size="sm"
            className="h-7 gap-1.5 text-[11px]"
            onClick={() => toast("Notification settings coming soon")}
          >
            <Settings className="size-3" />
            Preferences
          </Button>
          <Link
            href="/inbox"
            className="text-[11px] font-medium text-primary hover:underline"
          >
            View all in inbox →
          </Link>
        </div>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function FilterPill({
  active,
  onClick,
  label,
  count,
}: {
  active: boolean;
  onClick: () => void;
  label: string;
  count: number;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(
        "inline-flex items-center gap-1.5 rounded-md px-2.5 py-1 text-[11px] font-medium transition-colors",
        active
          ? "bg-background text-foreground shadow-[var(--shadow-xs)]"
          : "text-muted-foreground hover:text-foreground",
      )}
    >
      {label}
      <span
        className={cn(
          "tabular-nums",
          active ? "text-muted-foreground" : "text-muted-foreground/70",
        )}
      >
        {count}
      </span>
    </button>
  );
}

