  { label: "Inbox", href: "/inbox", hint: "Triage requests", icon: InboxIcon },
  { label: "Clients", href: "/clients", hint: "Client directory", icon: Users },
  { label: "Services", href: "/services", hint: "Productized services", icon: Wrench },
  { label: "Settings", href: "/settings", hint: "Workspace settings", icon: Settings },
  { label: "Billing", href: "/settings/billing", hint: "Plan & invoices", icon: CreditCard },
  { label: "Team", href: "/settings/team", hint: "Members & roles", icon: Users },
];

interface GlobalCommandLauncherProps {
  triggerClassName?: string;
}

export function GlobalCommandLauncher({ triggerClassName }: GlobalCommandLauncherProps) {
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [search, setSearch] = useState("");

  useEffect(() => {
    function onKeyDown(event: KeyboardEvent) {
      const mod = event.metaKey || event.ctrlKey;
      if (mod && event.key.toLowerCase() === "k") {
        // Don't steal ⌘K when the inbox palette is the active owner — but it
        // dispatches the same command, so whoever is mounted first wins.
        // The inbox workspace catches ⌘K locally; this only fires on non-inbox pages.
        if (window.location.pathname.startsWith("/inbox")) return;
        event.preventDefault();
        setOpen(true);
      }
    }
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, []);

  // External trigger: user menu dispatches this event
  useEffect(() => {
    function onOpenCommand() {
      if (window.location.pathname.startsWith("/inbox")) {
        // Let the inbox provider handle it
        window.dispatchEvent(new CustomEvent("clientloop:inbox-open-command"));
        return;
      }
      setOpen(true);
    }
    window.addEventListener("clientloop:open-command", onOpenCommand);
    return () => window.removeEventListener("clientloop:open-command", onOpenCommand);
  }, []);

  function handleOpenChange(next: boolean) {
    setOpen(next);
    if (!next) setSearch("");
  }

  function go(href: string) {
    handleOpenChange(false);
    router.push(href);
  }

  function showSoon(label: string) {
    handleOpenChange(false);
    toast(`${label} — coming soon`);
  }

  // Limit expensive lists for palette
  const topRequests = requests.slice(0, 6);
  const topClients = clients.slice(0, 6);

  return (
    <>
      <button
        type="button"
        onClick={() => setOpen(true)}
        aria-label="Open command palette"
        className={cn(
          "group relative hidden sm:flex h-9 w-48 md:w-64 items-center gap-2 rounded-md border border-transparent bg-muted/70 px-2.5 text-left text-sm text-muted-foreground transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
          triggerClassName,
        )}
      >
        <Search className="size-3.5 shrink-0" />
        <span className="flex-1 truncate text-[13px]">Search or jump to…</span>
        <span className="hidden md:flex items-center gap-0.5">
          <kbd className="rounded border border-border/60 bg-background/80 px-1 py-0.5 text-[9px] font-medium text-muted-foreground">
            ⌘
          </kbd>
          <kbd className="rounded border border-border/60 bg-background/80 px-1 py-0.5 text-[9px] font-medium text-muted-foreground">
            K
          </kbd>
        </span>
      </button>

      <CommandDialog open={open} onOpenChange={handleOpenChange}>
        <Command
          label="Global command palette"
          className="fixed left-1/2 top-[15%] z-50 w-[92vw] max-w-xl -translate-x-1/2 overflow-hidden rounded-2xl border border-border/70 bg-popover text-popover-foreground shadow-[var(--shadow-xl)] ring-1 ring-foreground/5"
        >
          <div className="flex items-center gap-2 border-b border-border/60 px-4 py-3">
            <CommandIcon className="size-4 text-muted-foreground" />
            <CommandInput
              value={search}
              onValueChange={setSearch}
              placeholder="Search pages, requests, clients…"
              className="flex-1 bg-transparent text-sm outline-none placeholder:text-muted-foreground"
            />
            <kbd className="rounded bg-muted px-1.5 py-0.5 text-[10px] font-medium text-muted-foreground">
              ESC
            </kbd>
          </div>

          <CommandList className="max-h-[60vh] overflow-y-auto px-1 py-2 text-sm">
            <CommandEmpty className="py-6 text-center text-xs text-muted-foreground">
              No matches.
            </CommandEmpty>

            <CommandGroup
              heading="Navigation"
              className="[&_[cmdk-group-heading]]:px-2 [&_[cmdk-group-heading]]:py-1.5 [&_[cmdk-group-heading]]:text-[10px] [&_[cmdk-group-heading]]:font-semibold [&_[cmdk-group-heading]]:uppercase [&_[cmdk-group-heading]]:tracking-wide [&_[cmdk-group-heading]]:text-muted-foreground"
            >
              {NAVIGATION.map((target) => {
                const Icon = target.icon;
                return (
                  <CommandItem
                    key={target.href}
                    value={`nav-${target.href} ${target.label} ${target.hint}`}
                    onSelect={() => go(target.href)}
                    className="flex items-center gap-2 rounded-md px-2 py-1.5 text-sm cursor-pointer data-[selected=true]:bg-primary/10"
                  >
                    <Icon className="size-3.5 text-muted-foreground" />
                    <span>{target.label}</span>
                    <span className="ml-auto text-[10px] text-muted-foreground">
                      {target.hint}
                    </span>
                    <ArrowRight className="size-3 text-muted-foreground/60" />
                  </CommandItem>
                );
              })}
            </CommandGroup>

            <CommandSeparator className="my-1 h-px bg-border/60" />

            <CommandGroup
              heading="Recent requests"
              className="[&_[cmdk-group-heading]]:px-2 [&_[cmdk-group-heading]]:py-1.5 [&_[cmdk-group-heading]]:text-[10px] [&_[cmdk-group-heading]]:font-semibold [&_[cmdk-group-heading]]:uppercase [&_[cmdk-group-heading]]:tracking-wide [&_[cmdk-group-heading]]:text-muted-foreground"
            >
              {topRequests.map((req) => (
                <CommandItem
                  key={req.id}
                  value={`req-${req.id} ${req.title} ${req.rawMessage}`}
                  onSelect={() => go("/inbox")}
                  className="flex items-center gap-2 rounded-md px-2 py-1.5 text-sm cursor-pointer data-[selected=true]:bg-primary/10"
                >
                  <InboxIcon className="size-3.5 text-muted-foreground" />
                  <span className="truncate">{req.title}</span>
                </CommandItem>
              ))}
            </CommandGroup>

            <CommandGroup
              heading="Clients"
              className="[&_[cmdk-group-heading]]:px-2 [&_[cmdk-group-heading]]:py-1.5 [&_[cmdk-group-heading]]:text-[10px] [&_[cmdk-group-heading]]:font-semibold [&_[cmdk-group-heading]]:uppercase [&_[cmdk-group-heading]]:tracking-wide [&_[cmdk-group-heading]]:text-muted-foreground"
            >
              {topClients.map((client) => (
                <CommandItem
                  key={client.id}
                  value={`client-${client.id} ${client.company} ${client.name}`}
                  onSelect={() => go("/clients")}
                  className="flex items-center gap-2 rounded-md px-2 py-1.5 text-sm cursor-pointer data-[selected=true]:bg-primary/10"
                >
                  <Users className="size-3.5 text-muted-foreground" />
                  <span className="truncate">{client.company}</span>
                  <span className="ml-auto text-[10px] text-muted-foreground">
                    {client.name}
                  </span>
                </CommandItem>
              ))}
            </CommandGroup>

            <CommandSeparator className="my-1 h-px bg-border/60" />

            <CommandGroup
              heading="Utilities"
              className="[&_[cmdk-group-heading]]:px-2 [&_[cmdk-group-heading]]:py-1.5 [&_[cmdk-group-heading]]:text-[10px] [&_[cmdk-group-heading]]:font-semibold [&_[cmdk-group-heading]]:uppercase [&_[cmdk-group-heading]]:tracking-wide [&_[cmdk-group-heading]]:text-muted-foreground"
            >
              <CommandItem
                value="util-shortcuts keyboard"
                onSelect={() => {
                  handleOpenChange(false);
                  window.dispatchEvent(new CustomEvent("clientloop:open-shortcuts"));
                }}
                className="flex items-center gap-2 rounded-md px-2 py-1.5 text-sm cursor-pointer data-[selected=true]:bg-primary/10"
              >
                <Keyboard className="size-3.5 text-muted-foreground" />
                Keyboard shortcuts
              </CommandItem>
              <CommandItem
                value="util-whats-new changelog"
                onSelect={() => showSoon("Changelog")}
                className="flex items-center gap-2 rounded-md px-2 py-1.5 text-sm cursor-pointer data-[selected=true]:bg-primary/10"
              >
                <Sparkles className="size-3.5 text-muted-foreground" />
                What&apos;s new
              </CommandItem>
              <CommandItem
                value="util-status system"
                onSelect={() => showSoon("System status")}
                className="flex items-center gap-2 rounded-md px-2 py-1.5 text-sm cursor-pointer data-[selected=true]:bg-primary/10"
              >
                <Gauge className="size-3.5 text-muted-foreground" />
                System status
              </CommandItem>
            </CommandGroup>
          </CommandList>
        </Command>
      </CommandDialog>
    </>
  );
}

